'use strict';
(() => {
const D=globalThis.RA.D;
const C=(senseId,domain,en,zh,structure,grammar,rationale)=>({senseId,domain,en,zh,structure,grammar,rationale,sourceType:'authored'});
const M=(wrong,right,reason,errorType='meaning')=>({wrong,right,reason,errorType});
const Q=(s,prompt,answer,wrong1,wrong2,explain,errorType='meaning')=>({s,prompt,answer,wrong1,wrong2,explain,errorType});
const E=(origin,w)=>({origin,prefix:null,root:null,suffix:null,source:`Etymonline: https://www.etymonline.com/word/${w.toLowerCase().replaceAll(' ','-')}`});
const P=(w,origin,contexts,mistake,qs)=>D(w,{etymology:E(origin,w),contexts:Array.isArray(contexts)?contexts:[contexts],mistakes:[mistake],quiz:qs.map((q,i)=>({id:`${w}.q${i+1}`,senseId:`${w}.s${q.s}`,prompt:q.prompt,answer:q.answer,options:[q.answer,q.wrong1,q.wrong2],explain:q.explain,errorType:q.errorType,type:'辨义与用法'}))});
P('stress','Stress entered English as a shortened form of distress for hardship or pressure; the sense of emphasis in speech is a later development.',[C('stress.s1','心理','After months of staff shortages, the nurse felt severe stress at work.','连续数月人手不足后，这名护士在工作中感到很大压力。','under stress; cause/reduce stress','名词，不可数，指忧虑或压力；也可指物体承受的力。','work conditions cause mental pressure.','心理'),C('stress.s2','语音','In “record” as a noun, the stress falls on the first syllable.','在名词 record 中，重音落在第一个音节上。','put/place stress on a syllable; word stress','名词，指口语中对音节或单词施加的额外力度。','first syllable receives emphasis.','语音'),C('stress.s3','表达','The report stresses that clean water must reach every village.','报告强调，清洁水必须送到每个村庄。','stress that + clause; stress the importance of','动词，指着重指出某个事实或观点。','report gives special importance to fact.','表达')],M('The report stressed that clean water mattered by saying it was completely unimportant.','The report stressed that clean water mattered to every village.','stress作动词表示强调，不能用来表达“完全不重要”。','meaning'),[Q(1,'Months of shortages caused the nurse severe stress. Here stress means…','mental pressure or worry','extra force on a spoken syllable','a long narrow piece of land','Sense 1 is the pressure caused by difficult conditions.','meaning'),Q(2,'In a spoken word, stress is…','extra force on a syllable','a feeling of worry only','a rule passed by a council','Sense 2 concerns pronunciation.','context'),Q(3,'If a report stresses a fact, it…','emphasizes that fact','removes it from the report','pronounces its first syllable','The verb means give special importance to an idea.','meaning'),Q(2,'Which phrase is standard for pronunciation?','the stress falls on the first syllable','the stress walks on the first syllable','the first syllable is a stress of','Stress can fall on a syllable to mark emphasis.','collocation')]);
P('stressful','Stressful is formed from stress + -ful; the suffix makes an adjective meaning that a situation causes worry or pressure.',C('stressful.s1','生活','Moving a parent into assisted living was stressful for the whole family.','把父母搬进辅助生活机构对全家来说都很有压力。','a stressful job/experience; find something stressful','形容词，描述引起焦虑或压力的事物；人通常说 stressed。','the situation causes strain for family.','生活'),M('The stressful interview caused no worry or pressure for anyone who took part.','The stressful interview left the applicants worried and under pressure.','stressful描述造成压力的事，原句却说毫无压力。','meaning'),[Q(1,'A stressful interview is one that…','causes worry or pressure','is completely relaxing','places emphasis on a syllable','Stressful describes a pressure-causing situation.','meaning'),Q(1,'Who found the move stressful?','The whole family','Only the assisted-living building','No one involved','The context says the move affected the family.','context'),Q(1,'Which sentence uses stressful correctly?','It was a stressful week at work.','I felt stressful after the exam.','She stressful finished her work.','Stressful describes the situation; a person usually feels stressed.','grammar'),Q(1,'Stressful is built from stress plus…','-ful','-less','-ment','The suffix -ful forms an adjective meaning full of or causing stress.','word-formation')]);
P('stretch','Stretch comes from Old English streccan, “extend or make taut”; it can mean pull longer, span a distance or period, or a continuous extent.',[C('stretch.s1','动作','The physiotherapist asked Lin to stretch her calf before the run.','理疗师让林在跑步前伸展小腿。','stretch a muscle; stretch your arms/legs','动词，指拉长或伸展身体部位。','the muscle is lengthened before exercise.','动作'),C('stretch.s2','范围','A low stone wall stretches along the north edge of the garden.','一道矮石墙沿着花园北边延伸。','stretch along/across; stretch for miles','动词，指在空间或时间上延伸。','wall extends over a line in space.','范围'),C('stretch.s3','时段','She worked a ten-hour stretch without taking a proper break.','她连续工作了十个小时，没有好好休息。','a long/continuous stretch; at a stretch','名词，指连续的一段距离、时间或活动。','ten hours form one uninterrupted period.','时段')],M('The wall stretches along the garden, but it ends at the first stone and covers no distance.','The wall stretches along the garden for several metres.','stretch along表示沿某一范围延伸，不是完全没有距离。','meaning'),[Q(1,'The physiotherapist asked Lin to stretch her calf. She should…','lengthen the muscle gently','make the muscle shorter by tying it','walk along the garden wall','Sense 1 refers to extending a body part.','meaning'),Q(2,'A wall that stretches along a garden…','extends beside it over some distance','is a ten-hour work period','cannot be seen','Sense 2 is spatial extension.','context'),Q(3,'A ten-hour stretch is…','a continuous period of ten hours','a flexible piece of cloth','a muscle exercise','Sense 3 is a continuous interval.','meaning'),Q(2,'Which use of stretch is grammatical?','The path stretches across the fields.','The path stretches the fields acrossly.','The path is a stretch acrossing.','Stretch across describes the path’s extent.','grammar')]);
P('stretch out','Stretch out combines stretch with the directional particle out; it means lie down and extend the body, or reach an arm or leg outward.',C('stretch out.s1','动作','After the hike, Noor stretched out on the grass and rested her legs.','徒步之后，努尔躺在草地上伸展身体，让双腿休息。','stretch out on a bed/sofa; stretch out an arm','短语动词，指躺下伸展身体，也可指把手脚伸向外面。','lying position and extended body after exertion.','动作'),M('After the hike, Noor stretched out by curling tightly into a ball and keeping every limb bent.','After the hike, Noor stretched out flat on the grass to rest.','stretch out指伸展开身体，与蜷缩成球相反。','meaning'),[Q(1,'Noor stretched out on the grass means she…','lay down and extended her body','stood stiffly without moving','walked along the grass','The phrasal verb describes reclining with the body extended.','meaning'),Q(1,'Why did Noor stretch out?','To rest her legs after hiking','To prepare a report','To measure the garden wall','The context links the action to resting after exertion.','context'),Q(1,'Which phrase is natural?','stretch out on the sofa','stretch out at the sofa on','stretching outly a sofa','On introduces the surface where someone lies.','collocation'),Q(1,'In stretch out, out suggests…','extension away from a bent or compact position','a strict rule','a person who strikes a ball','The particle adds the idea of extending outward.','word-formation')]);
P('stretcher','Stretcher is formed from stretch + -er; the word names a frame with a supporting surface used to carry someone who cannot walk.',C('stretcher.s1','急救','Paramedics secured the injured cyclist to a stretcher before moving him into the ambulance.','急救人员先把受伤的骑车人固定在担架上，再把他抬进救护车。','carry someone on a stretcher; stretcher-bearer','名词，指抬运伤病者的担架。','the frame carries a person unable to walk safely.','急救'),M('The paramedics put the cyclist on a stretcher so he could walk unaided to the ambulance.','The paramedics used a stretcher to carry the cyclist to the ambulance.','担架用于抬运伤病者，而不是让其自行行走。','meaning'),[Q(1,'A stretcher is used to…','carry an injured or ill person','stretch a garden wall','lock valuables in a box','That matches the medical transport sense.','meaning'),Q(1,'Why did paramedics secure the cyclist to it?','He needed to be carried safely','He was going for a run','He was learning to play a striker','The context describes transporting an injured person.','context'),Q(1,'Which phrase is correct?','carry the patient on a stretcher','carry the patient in a stretcher up','stretcher the patient carry on','On is the natural preposition with a stretcher.','collocation'),Q(1,'Stretcher is built from stretch plus…','-er','-ish','-ness','The suffix -er forms the name of a device used to support and carry.','word-formation')]);
P('stretchy','Stretchy is formed from stretch + -y; it describes a material that can be pulled longer and then recover its shape.',C('stretchy.s1','衣物','The waistband is stretchy, so the trousers remain comfortable when she sits.','腰带有弹性，所以她坐下时裤子仍然舒适。','stretchy fabric/material; stretchy waistband','形容词，指材料可被拉伸并通常能回弹。','elastic material yields during movement.','衣物'),M('The waistband is stretchy, but it snaps instead of lengthening when she sits.','The waistband is stretchy and lengthens slightly as she sits.','stretchy表示可拉伸，原句描述的是易断而非有弹性。','meaning'),[Q(1,'Stretchy fabric can…','be pulled and return toward its shape','never change shape when pulled','carry a patient on a frame','That is the material sense of stretchy.','meaning'),Q(1,'Why is the waistband comfortable?','It gives as she sits','It is made of stone','It prevents her from sitting','The example shows the material yielding with movement.','context'),Q(1,'Which phrase is natural?','stretchy jeans','stretchily jeans','stretchy of jeans','Stretchy directly modifies the clothing noun.','grammar'),Q(1,'Stretchy is formed from stretch plus…','-y','-er','-tion','The suffix -y forms an adjective meaning having the quality of stretching.','word-formation')]);
P('strew','Strew comes from Old English streowian, “scatter”; its past participle strewn describes things spread loosely over a surface.',C('strew.s1','散布','Wind had strewn pine needles across the path, making the stones hard to see.','风把松针吹得满路都是，石块因此不容易看见。','strew something over/around; be strewn with','动词，指把许多东西散撒在表面或各处；过去分词常作strewn。','needles lie scattered across a surface.','散布'),M('The wind strewn pine needles into a neat pile beside the path.','The wind strewn pine needles across the path.','strewn表示散落开来，整齐成堆与该语境不符。','verb-form'),[Q(1,'The wind strewn pine needles across the path means it…','scattered them over the surface','gathered every needle into a box','made the path longer','Strew means scatter things over an area.','meaning'),Q(1,'Why were the stones hard to see?','Pine needles covered parts of the path','The path was made of a stretcher','A storm removed all the needles','The context says the scattered needles obscured the stones.','context'),Q(1,'Which sentence is correct?','The floor was strewn with papers.','The floor strewn with papers yesterday.','The floor was strewed with paperses.','Strewn is the standard past participle in this construction.','verb-form'),Q(1,'Strew comes from Old English streowian, meaning…','scatter','stand firmly','speak with repeated sounds','The historical verb already meant to scatter.','word-formation')]);
P('stricken','Stricken is the irregular past participle of strike; in this adjective use, it means seriously harmed or overwhelmed by a disaster, illness, or grief.',C('stricken.s1','灾难','Volunteers delivered clean water to the drought-stricken villages.','志愿者把清洁水送到了遭受旱灾的村庄。','disaster-/poverty-/grief-stricken; stricken area','形容词，常与灾害、疾病、贫困或悲伤连用，表示受到严重打击。','drought has seriously affected villages.','灾难'),M('The drought-stricken village had abundant rain and suffered no damage from dry conditions.','The drought-stricken village had lost crops and needed emergency water.','drought-stricken表示受旱灾严重影响，丰雨无损与其相反。','meaning'),[Q(1,'A drought-stricken village is…','seriously affected by drought','a village with unlimited rainfall','a place where a striker scores','The compound means struck or harmed by drought.','meaning'),Q(1,'What did volunteers bring?','Clean water','A wooden stump','A strongbox','The context shows the villagers were affected by drought.','context'),Q(1,'Which phrase is natural?','grief-stricken families','stricken grief familiesly','grief-struckened families','Stricken commonly follows nouns naming a severe blow or condition.','collocation'),Q(1,'Stricken is the past participle of…','strike','strew','stride','The adjective is built on the irregular form strike–struck–stricken.','verb-form')]);
P('strict','Strict comes from Latin strictus, “drawn tight,” the past participle of stringere, “bind tight”; it describes exact rule-following or a narrow precise meaning.',[C('strict.s1','规则','The laboratory has strict rules for handling chemicals and disposing of waste.','实验室对化学品处理和废弃物处置有严格规定。','strict rules/standards; strict about something','形容词，指要求严守规章，几乎不容偏离。','procedures must be followed exactly.','规则'),C('strict.s2','定义','In the strict sense, a tomato is a fruit because it contains seeds.','严格按定义来说，番茄是水果，因为它含有种子。','in the strict sense; a strict definition','形容词，也指精确、限定范围的含义。','speaker signals a narrow technical definition.','定义')],M('The laboratory’s strict safety rule allowed staff to ignore it whenever they felt hurried.','The laboratory’s strict safety rule required staff to follow it every time.','strict规则要求严格遵守，不是随意忽略。','meaning'),[Q(1,'Strict laboratory rules…','must be followed exactly','are optional suggestions','describe a garden’s length','Sense 1 concerns demanding rules.','meaning'),Q(2,'“In the strict sense” signals…','a precise, limited definition','a relaxed opinion','a long period of work','Sense 2 narrows the meaning being discussed.','context'),Q(1,'Which phrase is standard?','strict about safety','strictly rules about','a strict of safety','Strict is an adjective used with about to name its subject.','grammar'),Q(1,'Latin strictus meant…','drawn tight','scattered loosely','walked slowly','The historical sense links strictness to something tightly bound.','word-formation')]);
P('strictly','Strictly is formed from strict + -ly; it means according to exact rules, or in a narrow and precise sense.',C('strictly.s1','规则','Visitors are strictly forbidden to touch the fragile instruments.','严禁访客触摸这些易损仪器。','strictly forbidden/controlled; strictly speaking','副词，修饰规则执行方式；也可用于“严格来说”。','the prohibition is enforced without exception.','规则'),M('Visitors are strictly forbidden to touch the instruments, so they may handle them whenever they wish.','Visitors are strictly forbidden to touch the instruments.','strictly forbidden表示严格禁止，与任意触摸矛盾。','meaning'),[Q(1,'If visitors are strictly forbidden to touch an object, they…','must not touch it under the rule','may touch it freely','must stretch it out','Strictly strengthens the rule’s force.','meaning'),Q(1,'What does the sign prohibit?','Touching the fragile instruments','Entering a studio after hours','Walking along the corridor','The example states the restricted action.','context'),Q(1,'Which phrase is natural?','strictly speaking','strict speakingly','speaking strictful','Strictly speaking is a set phrase meaning precisely stated.','collocation'),Q(1,'Strictly is formed by adding -ly to…','strict','stress','strew','The adjective strict takes -ly to make the adverb.','word-formation')]);
P('stride','Stride is an old Germanic word recorded in Old English; it describes walking with long decisive steps, and a long step or major progress.',[C('stride.s1','步行','The guide strode ahead, taking long steps over the muddy ground.','向导大步走在前面，跨过泥泞地面。','stride across/into; stride purposefully','动词，指迈着长而有力的步子行走。','long decisive steps are explicitly described.','步行'),C('stride.s2','进展','The new screening program was a major stride in preventing the disease.','新的筛查项目是预防这种疾病的一大进展。','make/take a stride; a major stride forward','名词，指跨步，也可比喻重大进展。','program advances prevention.','进展')],M('The guide strode ahead with tiny hesitant shuffles that barely moved him forward.','The guide strode ahead with long, confident steps.','stride表示大步而坚定地走，与细碎犹豫的步子不符。','meaning'),[Q(1,'The guide strode ahead means the guide…','walked with long decisive steps','sat down on a stretcher','walked in tiny shuffles','Sense 1 is a manner of walking.','meaning'),Q(2,'A major stride in prevention is…','a significant advance','a backward step with no progress','a strict definition','Sense 2 uses stride figuratively for progress.','context'),Q(1,'Which phrase is natural?','stride across the room','stride the room acrossly','stride to across the room','Across can mark the space crossed while striding.','collocation'),Q(1,'Which irregular past form is correct?','strode','strideded','stridden only','Stride has the past tense strode and past participle stridden.','verb-form')]);
P('strife','Strife came through Middle English and Old French; its deeper Germanic history is uncertain, but the word means angry conflict or bitter disagreement.',C('strife.s1','冲突','Years of political strife left the border region divided and economically weak.','多年的政治冲突使边境地区分裂、经济衰弱。','civil/political strife; strife between groups','名词，不可数，指个人、群体或国家之间激烈的冲突。','long conflict produces division.','冲突'),M('Political strife brought the rival groups into lasting agreement without argument or conflict.','Political strife kept the rival groups in angry conflict.','strife表示激烈冲突，与毫无争执的和解相反。','meaning'),[Q(1,'Political strife is…','angry conflict or bitter disagreement','a relaxed walk','a precisely followed laboratory rule','That is the meaning of strife.','meaning'),Q(1,'What resulted from years of strife?','The region became divided and economically weak','The region became a single strongbox','The groups agreed immediately','The context connects prolonged conflict with division.','context'),Q(1,'Which phrase is natural?','strife between rival groups','strife amongly rival groups','a strife of peacefully','Between identifies the sides in conflict.','collocation'),Q(1,'The deeper Germanic history of strife is…','uncertain','certainly the Latin word for a statue','known to mean stretch out','The source supports the Middle English/Old French path but not a settled deeper origin.','word-formation')]);
P('strike','Strike comes from Old English strīcan, “touch, rub, or hit”; it has senses including hit, stop work, occur suddenly, and light a match or make a deal.',[C('strike.s1','动作','A loose branch struck the roof during the storm.','暴风雨中，一根松动的树枝撞到了屋顶。','strike someone/something; strike hard','动词，指用力击打或撞击。','branch makes physical impact.','动作'),C('strike.s2','劳资','The nurses voted to strike unless management reopened pay negotiations.','护士们投票决定罢工，除非管理层重启薪酬谈判。','go on strike; strike for better pay','动词，指为争取待遇而拒绝工作。','workers withhold labor to press demands.','劳资'),C('strike.s3','想法','It suddenly struck Mei that she had left the keys at the clinic.','梅突然想到，她把钥匙落在诊所了。','it strikes someone that; strike someone as odd','动词，指想法突然进入脑中或给人某种印象。','realization comes suddenly.','想法'),C('strike.s4','动作','He struck a match to light the camping stove.','他划亮一根火柴，点燃露营炉。','strike a match/deal; strike a balance','动词，也指划火柴或达成协议。','action ignites a match.','动作')],M('The nurses voted to strike but continued working every shift as usual.','The nurses voted to strike and stop work until negotiations resumed.','此处strike指罢工，即暂时停止工作。','meaning'),[Q(1,'A branch struck the roof means it…','hit the roof','refused to work','suddenly seemed odd','Sense 1 is physical impact.','meaning'),Q(2,'The nurses voted to strike means they planned to…','stop working to press their pay demand','hit the hospital roof','light a match','Sense 2 is industrial action.','context'),Q(3,'It struck Mei that she had left the keys means…','the thought suddenly occurred to her','someone physically hit her','she began a labor dispute','Sense 3 describes a sudden realization.','meaning'),Q(4,'Which phrase uses strike in the match sense?','strike a match','strike the clinic that','strike a stricken','Strike a match means light it by friction.','collocation')]);
P('strike back','Strike back combines strike with back to express a response to an earlier attack or criticism; it can be physical or verbal.',C('strike back.s1','反击','After the rival team scored twice, the home side struck back with three goals.','对手连进两球后，主队连入三球反击。','strike back at an attacker; strike back with a response','短语动词，指受到攻击或批评后进行回击。','later goals answer the opponent’s earlier scoring.','反击'),M('The home side struck back by helping the rival team score again and making no response.','The home side struck back by scoring three goals in reply.','strike back表示回应对方的攻击，不是继续帮助对方。','meaning'),[Q(1,'The home side struck back means it…','responded to the rival’s earlier scoring','left the match before it began','stretched out on the field','Back signals a retaliatory response.','meaning'),Q(1,'How many goals did the home side score in reply?','Three','None','Two for the rival only','The context explicitly gives the home side three goals.','context'),Q(1,'Which phrase is natural?','strike back at an attacker','strike back an attacker atly','strike an attacker back to','At introduces the person receiving the response.','collocation'),Q(1,'In this phrasal verb, back adds the idea of…','returning a response to an earlier action','moving to the front of a queue','measuring physical height','The response answers a prior attack or criticism.','word-formation')]);
P('striker','Striker is formed from strike + -er; it can mean a worker taking part in a strike, a forward who scores goals, or a striking part in a mechanism.',[C('striker.s1','劳资','The striker joined the picket line outside the plant during the wage dispute.','薪酬争议期间，这名罢工工人加入了工厂外的纠察队。','a striking striker; union striker','名词，指参加罢工的工人。','worker withholds labor and joins picket.','劳资'),C('striker.s2','体育','The striker scored twice after moving into the center of the attack.','这名前锋移到进攻中路后梅开二度。','play as a striker; center striker','名词，指主要负责进球的前锋。','attacking player scores goals.','体育'),C('striker.s3','机械','The locksmith replaced the striker plate that the latch hits when the door closes.','锁匠更换了门关上时锁舌撞击的锁扣板。','door-lock striker; striker plate','名词，指锁具等装置里受撞击、使机构运作的部件。','latch hits component to engage lock.','机械')],M('The striker scored twice from defense, although the report identifies the player as the team’s goalkeeper.','The striker scored twice while playing as the team’s forward.','在足球语境里 striker 指前锋，不是守门员。','confusable'),[Q(1,'A striker on a picket line is…','a worker taking part in a labor protest','a lock component','a forward scoring goals','Sense 1 is the labor meaning.','meaning'),Q(2,'The striker scored twice. This player is most likely…','an attacking forward','a worker refusing to work','a latch plate','Sense 2 is the sports role.','context'),Q(3,'A door-lock striker is…','the part hit by the latch','the person who goes on strike','the door’s paint coating','Sense 3 names a mechanism component.','meaning'),Q(2,'Which phrase is natural in football?','play as a striker','strike as a strike worker','play strikerly at the goal','As introduces the player’s position.','collocation')]);
P('striking','Striking is formed from strike + -ing; the adjective means very noticeable, visually impressive, or unusually attractive.',[C('striking.s1','显著','There is a striking difference between the two maps: one shows a river that the other omits.','两张地图有明显差异：一张画出了河流，另一张却没有。','a striking contrast/difference; strikingly similar','形容词，指差异或特点格外醒目、容易注意到。','specific omission makes contrast stand out.','显著'),C('striking.s2','外貌','The actor wore a striking silver coat that caught everyone’s attention.','演员穿着一件醒目的银色外套，吸引了所有人的注意。','a striking appearance/design; look striking','形容词，也指外表或设计十分引人注目、漂亮。','unusual clothing attracts attention.','外貌')],M('The maps were strikingly different, but their only difference was a tiny label no reader could see.','The maps were strikingly different in their major features.','striking difference应当明显、显著，不是无人可见的细节。','meaning'),[Q(1,'A striking difference is…','a difference that is easy to notice','a difference that cannot be seen','a long period of work','Sense 1 concerns a conspicuous contrast.','meaning'),Q(2,'Why did the silver coat look striking?','Its unusual appearance caught people’s attention','It was hidden under another coat','It followed strict safety rules','The context explains its visual impact.','context'),Q(1,'Which phrase is natural?','a striking resemblance','a strikingly resemblance','a strike resemblance','Striking is the adjective before resemblance.','grammar'),Q(1,'Striking is formed from the verb…','strike','stroll','strew','The -ing form is used here as an adjective.','word-formation')]);
P('strikingly','Strikingly is formed from striking + -ly; it means to a degree that is conspicuous or strongly noticeable.',C('strikingly.s1','比较','The two independently designed logos are strikingly similar in shape and color.','这两个独立设计的标志在形状和颜色上惊人地相似。','strikingly different/similar; strikingly clear','副词，表示某种程度或相似/差异显著，容易引起注意。','unusual similarity stands out.','比较'),M('The two logos are strikingly similar, yet they share no visible feature at all.','The two logos are strikingly similar in shape and color.','strikingly similar要求存在显著相似之处，完全无相似与之矛盾。','meaning'),[Q(1,'Strikingly similar logos are…','similar in a way that is easy to notice','slightly similar in an invisible way','made from a stretcher','The adverb emphasizes conspicuous similarity.','meaning'),Q(1,'What features made the logos strikingly similar?','Their shape and color','Their different spelling only','Their hidden source code','The context names the shared visible features.','context'),Q(1,'Which sentence uses strikingly correctly?','The results were strikingly different.','The strikingly results differed.','The result was striking difference.','Strikingly modifies the adjective different.','grammar'),Q(1,'Strikingly is formed from striking plus…','-ly','-ness','-er','The suffix turns the adjective into an adverb.','word-formation')]);
P('string','String comes from Old English streng, “cord”; it names thin cord, a connected series, or the strings of an instrument, and can also be a verb.',[C('string.s1','绳线','Tie the parcel with string so the lid stays shut during delivery.','用细绳把包裹系好，这样运输时盖子就不会打开。','a piece/length of string; tie something with string','名词，不可数，指细绳或线。','cord holds the parcel closed.','绳线'),C('string.s2','连续','The team won a string of five games before the tournament ended.','比赛结束前，这支队伍连赢了五场。','a string of events/wins; a long string of','名词，指连续出现的一系列同类事物。','five wins occur one after another.','连续'),C('string.s3','装弦','The technician strung the old guitar with new steel strings.','技师给那把旧吉他装上了新的钢弦。','string a guitar/racket; string something with','动词，指给乐器装弦或用线串起物品。','new strings are fitted to the instrument.','装弦')],M('The parcel was tied with string, but the cord was cut so it could not hold the lid shut.','The parcel was tied tightly with string to keep the lid shut.','这里string用于捆扎，绳子必须系住包裹。','meaning'),[Q(1,'Tie the parcel with string means use…','thin cord','a written law','a long continuous period','Sense 1 is the cord used for tying.','meaning'),Q(2,'A string of five wins is…','five wins occurring one after another','one cord with five knots only','five unrelated losses','Sense 2 means a series.','context'),Q(3,'The technician strung the guitar means the technician…','put strings onto the instrument','tied the parcel closed','won five games','Sense 3 is the verb “fit with strings.”','meaning'),Q(1,'Which phrase is natural?','a string of victories','a string victories ofly','a victories stringing','Of introduces the items in the series.','collocation')]);
P('stringent','Stringent comes from Latin stringent-, the stem of stringere, “bind tight”; it describes rules or conditions that are very strict.',C('stringent.s1','规章','The new clinic adopted stringent checks for storing vaccines at the correct temperature.','新诊所采取了严格检查，确保疫苗按正确温度储存。','stringent rules/controls/requirements; stringent checks','形容词，指要求严苛、必须精确遵守。','temperature controls are enforced carefully.','规章'),M('The clinic’s stringent vaccine rules allowed staff to store doses at any temperature they preferred.','The clinic’s stringent vaccine rules required the specified storage temperature.','stringent规则限制严格，不能随意选择温度。','meaning'),[Q(1,'Stringent checks are…','very strict and demanding','optional and casual','long and narrow strips','That is the adjective’s sense.','meaning'),Q(1,'What did the clinic check?','Whether vaccines stayed at the required temperature','Whether a striker scored a goal','Whether string was tied around every bottle','The example names the controlled condition.','context'),Q(1,'Which collocation is natural?','stringent requirements','stringently requirements','a stringency requirements','Stringent is an adjective modifying requirements.','grammar'),Q(1,'The Latin source stringere meant…','bind tight','scatter widely','walk with long steps','Its historical meaning is consistent with the modern sense of strictness.','word-formation')]);
P('stringy','Stringy is formed from string + -y; it describes food containing tough fibres, or something made up of long thin strands.',C('stringy.s1','食物','The late-picked green beans were stringy and difficult to chew.','采摘太晚的四季豆纤维很粗，嚼起来费劲。','stringy meat/beans; stringy hair','形容词，指食物纤维筋丝多、难嚼；也可形容细长成丝的外观。','beans contain tough fibres.','食物'),M('The stringy beans were tender and completely free of fibrous strands.','The stringy beans contained tough fibres and were difficult to chew.','stringy描述纤维筋丝多，原句却说柔嫩无筋。','meaning'),[Q(1,'Stringy green beans are…','full of tough fibres','soft and entirely fibre-free','a series of five wins','That is the food-related sense.','meaning'),Q(1,'Why were the beans hard to chew?','They had tough strands','They were tied with string','They were frozen into a stretcher','The context says the beans had developed fibres.','context'),Q(1,'Which phrase is natural?','stringy meat','stringily meat','stringy of meat','Stringy directly modifies the noun.','grammar'),Q(1,'Stringy is formed from string plus…','-y','-er','-ment','The suffix -y makes an adjective meaning characterized by strings or fibres.','word-formation')]);
P('strip','Strip is recorded in Old English with the sense “plunder”; modern uses include removing a covering and a narrow piece or runway.',[C('strip.s1','去除','Workers stripped the cracked paint from the door before repainting it.','工人重新刷漆前先刮掉门上开裂的漆层。','strip paint/wire; strip something of something','动词，指去掉覆盖物或一层材料。','the old coating is removed.','去除'),C('strip.s2','形状','She cut a strip of reflective tape for the bicycle.','她为自行车剪下一条反光胶带。','a strip of land/paper/material','名词，指狭长的一条材料或区域。','a long narrow piece is cut.','形状'),C('strip.s3','地理','The pilot landed on a short dirt strip beside the farm.','飞行员在农场旁的一段短土跑道上降落。','an airstrip; a strip of shops','名词，也可指简易跑道或商业街。','the plane uses a short runway.','地理')],M('Workers stripped the old paint by covering it with a new coat and removing nothing.','Workers stripped the old paint off the door before repainting it.','strip paint表示去除旧漆，不是覆盖旧漆。','meaning'),[Q(1,'To strip old paint is to…','remove the coating','add another coat without removing it','cut paint into narrow bands','Sense 1 is the verb meaning remove.','meaning'),Q(2,'A strip of reflective tape is…','a long narrow piece','a round metal box','a strict rule','Sense 2 names a narrow band of material.','context'),Q(3,'A dirt strip beside a farm may be…','a simple runway','a coat of paint','a ribbon only','Sense 3 can mean an airstrip.','meaning'),Q(1,'Which phrase is natural?','strip bark from a branch','strip bark to a branch','striply bark from branch','From introduces the material removed.','collocation')]);
P('stripe','Stripe is recorded in English from a Germanic source related to Middle Dutch stripe; it means a narrow band of color, a rank mark, or a type.',[C('stripe.s1','颜色','A yellow stripe runs down the center of the dark blue jersey.','深蓝色球衣中央有一道黄色条纹。','a stripe of color; striped shirt','名词，指与周围颜色不同的细长色带。','the contrasting band is visible.','颜色'),C('stripe.s2','等级','The corporal earned a second stripe on her uniform after the promotion.','晋升后，这名下士的制服上多了一道军衔条。','earn/wear a stripe; people of every stripe','名词，也指军衔标记，或比喻某一类人。','the uniform mark indicates rank.','等级')],M('The jersey has a yellow stripe, a round blue dot with no length or band shape.','The jersey has a long yellow stripe against its blue fabric.','stripe是细长色带，不是圆点。','meaning'),[Q(1,'A yellow stripe on a jersey is…','a long narrow band of color','a round button','a regulation','Sense 1 concerns a colored band.','meaning'),Q(2,'A stripe on a corporal’s uniform may show…','rank','a runway','a tree stump','Sense 2 is rank insignia.','context'),Q(2,'“People of every stripe” means people…','of many different kinds','wearing the same rank mark','who are all strikers','Stripe can figuratively mean type.','meaning'),Q(1,'Which phrase is correct?','a blue-and-white striped shirt','a stripe shirted blue white','a blue stripedly shirt','Striped is the adjective formed from stripe.','grammar')]);
P('stripper','Stripper is formed from strip + -er; it names a tool or chemical that removes paint or another covering, and can also name an entertainer who removes clothing.',C('stripper.s1','工具','Use a paint stripper outdoors and wear gloves to avoid breathing its fumes.','在室外使用脱漆剂，并戴手套避免吸入挥发气体。','paint/wire stripper; chemical stripper','名词，指去除漆层、绝缘层等覆盖物的工具或化学剂；也可指脱衣表演者。','the chemical removes a paint layer.','工具'),M('The paint stripper protected the old coating and made it impossible to remove.','The paint stripper softened the old coating so it could be removed.','paint stripper用于去除涂层，不是保护涂层。','meaning'),[Q(1,'A paint stripper is…','a product that removes paint','a painter of narrow stripes','a locked document box','The word names a paint-removing product here.','meaning'),Q(1,'Why use it outdoors?','Its fumes may be harmful to breathe','It needs a stronghold to work','It is a performer on a stage','The context mentions fumes and ventilation.','context'),Q(1,'Which phrase is natural?','a chemical stripper for old paint','a chemical strip the old paint','stripperly chemical for paint','Stripper is a count noun modified by chemical.','grammar'),Q(1,'Stripper is built from strip plus…','-er','-ful','-ity','-er can name a tool or agent doing the action.','word-formation')]);
P('strive','Strive came through Middle English and Old French; its deeper origin is uncertain. It means make a determined effort, often against difficulty.',[C('strive.s1','努力','The clinic strives to offer every patient an appointment within a week.','诊所努力让每位患者都能在一周内获得预约。','strive to do; strive for excellence','动词，指努力实现目标。','the clinic makes a sustained effort.','努力'),C('strive.s2','抗争','Local groups strove against closure of the only rural bus route.','当地团体奋力反对关闭唯一的乡村公交线路。','strive against hardship/opposition','动词，也可强调与阻力或困难斗争。','groups oppose a difficult policy.','抗争')],M('The clinic strives to cut waits by refusing to accept any appointments.','The clinic strives to cut waits by adding appointment slots.','strive to表示努力达成目标，拒绝预约会阻碍目标。','meaning'),[Q(1,'The clinic strives to offer appointments means it…','makes a determined effort to do so','has given up trying','walks with long steps','Sense 1 is purposeful effort.','meaning'),Q(2,'Groups strove against a route closure means they…','worked hard to oppose it','supported it without question','removed a layer of paint','Sense 2 highlights struggle against opposition.','context'),Q(1,'Which construction is correct?','strive to improve access','strive improving access to','strive for to improve access','Strive commonly takes to plus a verb.','grammar'),Q(1,'The deeper origin of strive is…','uncertain','certainly Latin for a stripe','certainly Old English for a stump','Its path through Middle English/French is known, but the ultimate source is not settled.','word-formation')]);
P('stroke','Stroke is recorded in Old English as a blow or movement; it can mean a hit or motion, a medical attack, gentle touching, or a swimming style.',[C('stroke.s1','动作','With one stroke of the saw, the carpenter cut through the thin board.','木匠用锯子一拉，就锯断了那块薄木板。','a stroke of a pen/luck; one stroke','名词，指击打或重复动作中的一次。','one movement completes the cut.','动作'),C('stroke.s2','健康','The hospital team assessed the patient for signs of a stroke.','医院小组检查病人是否有中风迹象。','suffer/have a stroke; stroke symptoms','名词，指脑部供血受阻或脑血管破裂造成的突发疾病。','the team evaluates an acute condition.','健康'),C('stroke.s3','触摸','She stroked the nervous dog gently until it stopped trembling.','她轻轻抚摸那只紧张的狗，直到它不再发抖。','stroke a pet’s fur; gently stroke','动词，指用手轻轻抚过动物或表面。','gentle touch calms the dog.','触摸'),C('stroke.s4','游泳','The coach corrected his butterfly stroke during the first lap.','教练在第一圈时纠正了他的蝶泳动作。','swimming stroke; breaststroke/backstroke','名词，指游泳姿势或一次划水。','the swimming technique is corrected.','游泳')],M('One stroke of the saw means the carpenter left it untouched and made no cutting movement.','One stroke of the saw carried the blade through the board.','stroke在此表示一次切割动作。','meaning'),[Q(1,'One stroke of the saw is…','one cutting movement','a brain emergency','a swimming style','Sense 1 names one movement.','meaning'),Q(2,'Doctors checking for signs of stroke are checking for…','a sudden brain-related medical condition','a swimming technique','a petting motion','Sense 2 is the medical condition.','context'),Q(3,'She stroked the dog means she…','moved her hand gently over its fur','hit it with a saw','swam butterfly stroke','Sense 3 describes gentle touching.','meaning'),Q(4,'A butterfly stroke is…','a swimming style','a medical attack','a piece of reflective tape','Sense 4 is a named swimming technique.','context')]);
P('stroll','Stroll is recorded in English from the 16th century; its deeper origin is uncertain. It means walk slowly and casually, or a relaxed walk.',[C('stroll.s1','散步','They strolled along the canal after dinner, stopping to watch the boats.','晚饭后，他们沿运河慢慢散步，停下来看看船。','stroll along/through; stroll around town','动词，指缓慢、轻松地步行。','the walk is unhurried and includes stops.','散步'),C('stroll.s2','散步','We took a short stroll through the park before the rain began.','下雨前，我们在公园里短暂散了会儿步。','go for/take a stroll; a leisurely stroll','名词，指一次放松的慢步行。','a short recreational walk is taken.','散步')],M('They strolled along the canal by sprinting at full speed without stopping.','They strolled along the canal at an easy pace.','stroll表示轻松慢行，不是全速冲刺。','meaning'),[Q(1,'They strolled after dinner means they…','walked slowly and casually','ran a timed race','sat in a strongbox','Sense 1 is an unhurried walk.','meaning'),Q(2,'A short stroll through a park is…','a relaxed walk','a swimming style','a long labor dispute','Sense 2 is the noun for a casual walk.','context'),Q(1,'Which phrase is natural?','stroll along the canal','stroll the canal alongly','stroll to along the canal','Along marks the route.','collocation'),Q(1,'The deeper origin of stroll is…','uncertain','certainly Latin for “strict”','certainly Old English for “cord”','Its earlier derivation is not settled.','word-formation')]);
P('strong','Strong comes from Old English strang, “powerful”; it describes durability, intensity, skill, or a firmly held view.',[C('strong.s1','力量','The strong canvas bag held the tools without tearing.','结实的帆布袋装着工具，没有被撕破。','strong material/structure; physically strong','形容词，指身体有力或物体坚固耐用。','the bag resists weight and does not tear.','力量'),C('strong.s2','程度','A strong smell of smoke remained in the curtains after the fire.','火灾后，窗帘上仍有浓重的烟味。','strong smell/taste/wind; strong evidence','形容词，也指程度、味道或效果强烈。','the odor is intense.','程度'),C('strong.s3','能力','Maya is strong in statistics and helps classmates interpret data.','玛雅擅长统计学，还帮助同学解读数据。','strong in a subject; strong on details','形容词，也指擅长某领域或立场坚定。','her skill in statistics is highlighted.','能力')],M('The strong canvas tore as soon as one light tool was placed inside it.','The strong canvas held the tools without tearing.','strong描述耐用，与轻易撕裂相反。','meaning'),[Q(1,'A strong canvas bag is…','not easily torn','full of smoke','a relaxed walk','Sense 1 concerns durability.','meaning'),Q(2,'A strong smell of smoke is…','intense and easy to notice','weak and almost absent','a firm opinion','Sense 2 concerns intensity.','context'),Q(3,'Maya is strong in statistics means she…','is skilled in the subject','has a durable bag','dislikes statistics','Sense 3 describes ability.','meaning'),Q(1,'Which phrase is natural?','a strong smell of smoke','strongly smell of smoke','a strength smell smoke','Strong is the adjective before smell.','collocation')]);
P('strongbox','Strongbox combines strong + box; it names a heavy, securely locked box used to protect valuables or important papers.',C('strongbox.s1','保管','The archivist placed the signed deeds in a strongbox before renovation.','档案员在翻修前把签署过的契据放进保险箱。','lock/store valuables in a strongbox; metal strongbox','名词，指带牢固锁具、用来保管贵重物品或文件的箱子。','important papers are secured from theft or loss.','保管'),M('The deeds were kept in a strongbox whose lid had no lock and fell open.','The deeds were kept in a locked strongbox for protection.','strongbox用牢固锁具保护物品。','meaning'),[Q(1,'A strongbox is mainly used to…','keep valuables or documents secure','carry an injured person','store stringy food','Its sturdy lock protects what is inside.','meaning'),Q(1,'What did the archivist put in it?','Signed deeds','Reflective tape','A swimming stroke','The context identifies the protected papers.','context'),Q(1,'Which phrase is natural?','a locked metal strongbox','a strongboxly metal locked','a strong metal of box','Strongbox is a compound noun modified by locked and metal.','grammar'),Q(1,'Strongbox combines strong with…','box','stripe','stroll','The compound names a reinforced box.','word-formation')]);
P('stronghold','Stronghold combines strong + hold, “a fortified place”; figuratively it is a region where a party or group has many supporters.',[C('stronghold.s1','防守','The rebels retreated to a mountain stronghold with thick walls and a guarded gate.','叛军撤入一座山间据点，那里城墙厚实、大门有人把守。','a fortified stronghold; retreat to a stronghold','名词，指防守坚固、难以攻占的地方。','defenses make the site hard to capture.','防守'),C('stronghold.s2','支持','The coastal district remains a stronghold of the labor party despite losses elsewhere.','尽管该党在其他地区失利，这个沿海区仍是工党的稳固支持区。','a stronghold of a party/group; traditional stronghold','名词，也指某组织或信仰支持者集中的地区。','local voters continue to support the party.','支持')],M('The party’s stronghold was the one district where it had no supporters and lost every vote.','The party’s stronghold was the district where its supporters remained concentrated.','比喻义stronghold指支持者集中的地方。','meaning'),[Q(1,'A mountain stronghold is…','a well-defended place','a relaxed walk','a thin cord','Sense 1 is the fortified-place meaning.','meaning'),Q(2,'A party stronghold is a district where…','the party has many supporters','the party has no voters','voting is forbidden','Sense 2 means an area of strong support.','context'),Q(1,'Which phrase is natural?','a stronghold of the opposition','a stronghold the opposition ofly','stronghold into opposition','Of introduces the group supported.','collocation'),Q(1,'Stronghold combines strong with…','hold, a fortified place','stroll, a relaxed walk','stringent, strict rules','The compound evokes a place that can be held defensively.','word-formation')]);
P('strongly','Strongly is formed from strong + -ly; it means with force or intensity, or with a firmly held opinion.',C('strongly.s1','程度','The evidence strongly suggests that the bridge needs urgent repairs.','证据强烈表明这座桥需要紧急维修。','strongly suggest/recommend/oppose; strongly built','副词，表示程度高、力量大或立场坚定。','evidence supports a forceful conclusion.','程度'),M('The evidence strongly suggests repairs are needed, but it provides no support for that conclusion.','The evidence strongly suggests that urgent repairs are needed.','strongly suggests表达有力支持，不是毫无证据。','meaning'),[Q(1,'Evidence strongly suggests a conclusion when it…','supports it with considerable force','rules it out completely','is physically durable','Strongly intensifies the suggestion.','meaning'),Q(1,'What does the evidence indicate about the bridge?','It needs urgent repairs','It is already a strongbox','It should be used for swimming','The context gives the supported conclusion.','context'),Q(1,'Which sentence is correct?','I strongly recommend the safety inspection.','I strong recommend the inspection.','I recommend stronglyly the inspection.','Strongly is the adverb modifying recommend.','grammar'),Q(1,'Strongly is formed from strong plus…','-ly','-er','-ment','The suffix -ly forms an adverb.','word-formation')]);
P('structural','Structural is formed from structure + -al; it means relating to the arrangement and interconnection of parts in a building, system, or text.',C('structural.s1','工程','Engineers found structural damage in two support beams after the earthquake.','地震后，工程师发现两根承重梁出现结构性损坏。','structural damage/support/change; structural engineer','形容词，指涉及结构组成、组织方式或承力构造。','damage affects the load-bearing frame.','工程'),M('The inspector found structural damage, but every supporting beam and joint was completely intact.','The inspector found structural damage in the bridge’s supporting frame.','structural damage涉及构造部件，与结构完好矛盾。','meaning'),[Q(1,'Structural damage to a bridge affects…','its supporting framework','the color of its road signs only','a striker’s position','The adjective concerns arrangement and support of parts.','meaning'),Q(1,'Where was damage found?','In two support beams','In a strongbox lock','In the nearby river','The context names the load-bearing beams.','context'),Q(1,'Which phrase is natural?','a structural weakness','a structurally weakness','a structure weaknessly','Structural is an adjective modifying weakness.','grammar'),Q(1,'Structural is formed from structure plus…','-al','-er','-ish','The suffix -al creates an adjective meaning related to the noun.','word-formation')]);
P('structuralism','Structuralism is formed from structural + -ism; it names approaches that analyze systems of relations rather than treating elements in isolation.',C('structuralism.s1','学术','In the seminar, structuralism was used to compare recurring oppositions across several myths.','研讨课上，大家用结构主义比较几则神话中反复出现的对立关系。','structuralism in linguistics/literary theory; structuralist analysis','名词，指研究关系系统而非孤立项目的理论路径。','patterns across myths, not isolated details, are analyzed.','学术'),M('The essay followed structuralism by ignoring every relation between elements and studying each one alone.','The essay followed structuralism by examining relations linking the elements.','结构主义重视关系系统，孤立分析与其相反。','meaning'),[Q(1,'Structuralism focuses on…','systems of relations among elements','isolated items with no connections','the strength of a building beam','That is the theoretical approach named here.','meaning'),Q(1,'How were the myths compared?','Through recurring oppositions across them','By measuring building materials','By counting only their titles','The example emphasizes repeated relational patterns.','context'),Q(1,'Which phrase is natural?','structuralism in literary theory','structuralist in literary theoryism','a structuralism theory ofly','The noun can name an approach within a field.','grammar'),Q(1,'Structuralism is formed from structural plus…','-ism','-ful','-ize','The suffix -ism commonly names a doctrine or approach.','word-formation')]);
P('structurally','Structurally is formed from structural + -ly; it means with regard to the arrangement, organization, or physical framework of something.',C('structurally.s1','工程','The building is structurally sound, although its paint and windows need repair.','这栋建筑结构稳固，不过油漆和窗户需要维修。','structurally sound/weak/complex; structurally similar','副词，表示从结构组织或承力角度来看。','the framework is safe despite surface defects.','工程'),M('The building is structurally sound, yet its main frame cannot support its own weight.','The building is structurally sound and its frame safely supports the load.','structurally sound表示结构安全，不能承受自重则不稳固。','meaning'),[Q(1,'Structurally sound means the building’s…','framework is safe and stable','paint is attractive','windows are recently cleaned','The adverb refers to the construction framework.','meaning'),Q(1,'What still needed repair?','The paint and windows','The safe main frame','A lock’s striker plate','The context separates surface repairs from structural condition.','context'),Q(1,'Which sentence is correct?','The two plans are structurally similar.','The two plans are structural similar.','Structurally, the plans similar are.','Structurally modifies the adjective similar.','grammar'),Q(1,'Structurally is formed from structural plus…','-ly','-ness','-er','The adverb suffix is added to structural.','word-formation')]);
P('structure','Structure comes from Latin structura, from struere, “build”; it means the arrangement of parts, a built object, or the act of organizing something.',[C('structure.s1','组织','The report’s structure moves from the problem to evidence and then to recommendations.','报告的结构依次从问题谈到证据，再提出建议。','the structure of a text/system; organizational structure','名词，指各部分安排和相互关系的方式。','sections follow a deliberate order.','组织'),C('structure.s2','建筑','A wooden structure beside the trail shelters hikers from the rain.','步道旁的一座木结构建筑为徒步者遮雨。','a stone/wooden structure; ancient structures','名词，也指建造出来的实体物体。','the built object provides shelter.','建筑'),C('structure.s3','安排','The teacher structured the debate so each side had time to present evidence.','老师安排了辩论流程，让双方都有时间陈述证据。','structure something around/into; structure a response','动词，指按清楚框架安排内容或活动。','the debate has balanced speaking turns.','安排')],M('The report has a clear structure, but its sections are placed randomly with no order or relation.','The report has a clear structure, with sections arranged in a logical order.','structure指各部分的组织方式，随机排列不构成清晰结构。','meaning'),[Q(1,'The structure of a report is…','the way its parts are arranged','a person’s long step','the color of a stripe','Sense 1 concerns organization.','meaning'),Q(2,'A wooden structure beside a trail is…','a built physical object','a theory of myths','a medical attack','Sense 2 is a constructed object.','context'),Q(3,'The teacher structured the debate means the teacher…','organized its parts and sequence','built a wooden shelter','walked with long steps','Sense 3 is the verb meaning arrange.','meaning'),Q(1,'Structure comes from Latin structura, related to…','struere, “build”','strīcan, “hit”','stincan, “smell”','The source is associated with building or putting together.','word-formation')]);
P('struggle','Struggle is recorded in Middle English; its deeper Germanic/French pathway is uncertain. It means make a hard effort, fight against opposition, or such an effort itself.',[C('struggle.s1','努力','The child struggled to open the jar, then asked her brother for help.','孩子费力地拧罐子，随后请哥哥帮忙。','struggle to do; struggle with a task','动词，指努力做困难的事。','opening the jar requires effort.','努力'),C('struggle.s2','抗争','Residents struggled against the plan to close their only health center.','居民们奋力反对关闭他们唯一卫生中心的计划。','struggle against/for; struggle with a problem','动词，指与人或问题抗争。','residents oppose a policy.','抗争'),C('struggle.s3','奋斗','For the family, finding affordable housing became a daily struggle.','对这家人来说，寻找负担得起的住房成了每日难题。','a daily/long struggle; a struggle for survival','名词，指艰难努力或长期斗争。','an ongoing challenge requires repeated effort.','奋斗')],M('Residents struggled against the clinic closure by campaigning to make sure it happened quickly.','Residents struggled against the clinic closure by organizing a campaign to prevent it.','struggle against表示反对、抗争，不是推动该计划。','meaning'),[Q(1,'The child struggled to open the jar means she…','made a hard effort to open it','opened it effortlessly','removed a layer of paint','Sense 1 concerns effort.','meaning'),Q(2,'Residents struggling against closure are…','trying to prevent the closure','campaigning to speed it up','taking a relaxed walk','Sense 2 is opposition to a plan.','context'),Q(3,'A daily struggle is…','a recurring difficult effort','a secure metal box','a swimming movement','Sense 3 is the noun for an ongoing challenge.','meaning'),Q(1,'Which construction is correct?','struggle to find housing','struggle finding to housing','struggle at to find housing','Struggle commonly takes to plus a verb.','grammar')]);
P('struggler','Struggler is formed from struggle + -er; it refers to someone who keeps trying despite difficulty, often without quick success.',C('struggler.s1','学习','The reading program gives a struggler short passages and time to reread them.','阅读项目为阅读有困难的学生提供短文和重读的时间。','a struggling learner; support a struggler','名词，指努力应对困难、进展不易的人。','short tasks support a learner facing difficulty.','学习'),M('The teacher called him a struggler because every task was effortless and he never faced difficulty.','The teacher called him a struggler because he kept trying through difficult reading tasks.','struggler指努力克服困难的人，不能仅因毫不费力这么称呼。','meaning'),[Q(1,'A struggler in a reading program is…','a learner facing difficulty but continuing to try','a student who never studies','a sports striker','The term refers to someone working through difficulty.','meaning'),Q(1,'What support did the program provide?','Short passages and time to reread','A strongbox for books','A swimming lesson only','The context shows targeted reading support.','context'),Q(1,'Which phrase is natural?','a struggler with reading','a struggler readingly with','struggle person at reading','With introduces the area of difficulty.','collocation'),Q(1,'Struggler is formed from struggle plus…','-er','-ous','-al','The suffix -er names a person associated with the action.','word-formation')]);
P('strut','Strut is recorded in English from the 14th century; its earlier origin is uncertain. It means walk stiffly and proudly to show self-importance.',C('strut.s1','举止','The peacock strutted across the courtyard with its tail raised.','孔雀昂首挺胸地穿过庭院，尾巴高高翘起。','strut across/around; strut about proudly','动词，指摆出神气姿态、僵硬而骄傲地走。','the bird displays itself while walking.','举止'),M('The peacock strutted modestly by keeping its tail down and hiding behind a wall.','The peacock strutted across the courtyard with its tail spread proudly.','strut表示神气地走、展示自己，与躲藏低调相反。','meaning'),[Q(1,'The peacock strutted across the courtyard means it…','walked proudly with a showy posture','ran quietly to hide','stumbled over a stone','That is the verb’s manner-of-walking sense.','meaning'),Q(1,'What made its walk look showy?','Its raised, displayed tail','A stripe on a shirt','A wooden stump','The context describes a proud display.','context'),Q(1,'Which phrase is natural?','strut around the stage','strut the stage aroundly','strutting aroundly the stage','Around marks the area where someone struts.','collocation'),Q(1,'The earlier origin of strut is…','uncertain','certainly Latin for “build”','certainly French for “small box”','The first English records are known, but a deeper derivation is not secure.','word-formation')]);
P('stub','Stub has Old and Middle English relatives meaning a stump or short remaining piece; it names such a remnant, a ticket counterfoil, or painfully hitting a toe.',[C('stub.s1','残段','Only a stub of candle remained, too short to light the room.','只剩下一小截蜡烛，短得不足以照亮房间。','a candle/pencil stub; stub of a cigarette','名词，指用剩后留下的短小硬段。','a small remnant is left.','残段'),C('stub.s2','凭据','Keep the ticket stub until the concert venue confirms the refund.','保留票根，直到演出场馆确认退款。','ticket/check stub; tear off a stub','名词，指票据上撕下或保留作记录的一部分。','the counterfoil serves as a record.','凭据'),C('stub.s3','碰撞','I stubbed my toe on the low table while carrying a box.','我搬箱子时脚趾撞到了矮桌子。','stub one’s toe; stub a cigarette out','动词，指脚趾端疼痛地撞到硬物；也可把烟头按灭。','the toe hits a hard obstacle.','碰撞')],M('I stubbed my toe on the table, but my foot never touched it and there was no pain.','I stubbed my toe painfully against the table leg.','stub one’s toe指脚趾撞到硬物，原句否认接触和疼痛。','meaning'),[Q(1,'A candle stub is…','a short piece left after most was used','a full new candle','a strong opinion','Sense 1 is the remnant meaning.','meaning'),Q(2,'Why keep a ticket stub?','It serves as a record of the ticket','It lights a match','It is a narrow color band','Sense 2 is the retained ticket portion.','context'),Q(3,'He stubbed his toe means he…','hit the end of his toe against something','cut a strip of paper','walked proudly across a stage','Sense 3 is the painful collision.','meaning'),Q(1,'Which phrase is standard?','stub your toe on a table','stub your toe to a table','stubly your toe at a table','On marks the hard object struck.','collocation')]);
P('stubble','Stubble is related to stub, a short stump or remnant; it names short stalks left after crops are cut, or rough short beard growth.',[C('stubble.s1','农事','After the wheat harvest, short stubble covered the field until plowing began.','小麦收割后，短茬覆盖着田地，直到开始犁地。','wheat/corn stubble; stubble field','名词，不可数，指收割后留在地里的短茎。','cut stalks remain rooted in the field.','农事'),C('stubble.s2','外貌','A day of stubble showed along his jaw after the overnight flight.','经过一夜飞行后，他的下颌冒出了一天没刮的短胡茬。','a day’s stubble; beard stubble','名词，不可数，也指剃后刚长出的短硬胡茬。','short beard growth is visible.','外貌')],M('The wheat field was covered with tall uncut stalks, which the report called stubble.','The field was covered with short stalks left after the wheat harvest.','stubble指收割后留下的短茬，不是高大的未收割作物。','meaning'),[Q(1,'Wheat stubble is…','short stalks left after harvesting','a crop not yet cut','a ticket counterfoil','Sense 1 is agricultural.','meaning'),Q(2,'A day of stubble on someone’s jaw is…','short rough beard growth','a day spent walking in a field','a candle remnant','Sense 2 is the facial-hair meaning.','context'),Q(1,'Which phrase is natural?','beard stubble','stubble of beardedly','a beard stubble hairs','Stubble can directly modify beard as a noun adjunct.','grammar'),Q(1,'Stubble is related to stub, meaning…','a short stump or remaining piece','an exact rule','a swimming style','Both refer to short remnants.','word-formation')]);
P('stubborn','Stubborn is recorded in Middle English; its deeper etymology is uncertain. It describes someone unwilling to change a view, or something difficult to remove or alter.',[C('stubborn.s1','态度','The stubborn witness refused to change her account even after seeing the new video.','这名固执的目击者看过新视频后仍拒绝改变说法。','a stubborn person; stubborn about something','形容词，指即使可能不对也不愿改变态度或主意。','she holds her position despite contrary evidence.','态度'),C('stubborn.s2','难除','The mechanic used a solvent to remove a stubborn oil stain from the seat.','技工用溶剂去除座椅上顽固的油渍。','a stubborn stain/problem/cough; stubborn to remove','形容词，也指很难去掉、治愈或改变的事物。','the stain resists ordinary cleaning.','难除')],M('The stubborn oil stain vanished immediately with a dry cloth and needed no cleaning effort.','The stubborn oil stain resisted ordinary cleaning and needed solvent.','stubborn在物品语境中表示难以去除，不是轻易消失。','meaning'),[Q(1,'A stubborn witness is…','unwilling to change her position','quick to agree with every claim','a heavy locked box','Sense 1 concerns attitude.','meaning'),Q(2,'A stubborn oil stain is…','difficult to remove','a stain that disappears at once','a stripe on a uniform','Sense 2 applies stubborn to a resistant problem.','context'),Q(1,'Which phrase is natural?','a stubborn refusal to apologize','a stubbornly refusal to apologize','stubbornness refusally to apologize','Stubborn is an adjective before refusal.','grammar'),Q(1,'The deeper historical origin of stubborn is…','uncertain','certainly Latin for “cord”','certainly the suffix -ful','Middle English is recorded, but the earlier derivation is not secure.','word-formation')]);
P('stubbornness','Stubbornness is formed from stubborn + -ness; it names a person’s determined refusal to change a view or course of action.',C('stubbornness.s1','态度','Her stubbornness kept the negotiations from moving forward, even after both sides offered compromises.','即使双方都提出了妥协方案，她的固执仍使谈判无法推进。','stubbornness about/over something; overcome stubbornness','名词，指拒绝改变想法或做法的固执态度。','she rejects compromise and blocks progress.','态度'),M('His stubbornness made him change his position every time a new proposal arrived.','His stubbornness made him refuse to reconsider his position.','stubbornness表示不愿改变立场，与不断改主意相反。','meaning'),[Q(1,'Stubbornness is…','a determined refusal to change a view','a willingness to accept every proposal','the strength of a building','That is the noun’s sense.','meaning'),Q(1,'Why did negotiations stop?','She refused to accept compromises','Both sides ran out of paper','The room was structurally sound','Her unwillingness to change blocked progress.','context'),Q(1,'Which phrase is natural?','stubbornness about the decision','stubbornness decisionly about','stubborn of decisionness','About introduces the topic of the refusal to change.','collocation'),Q(1,'Stubbornness is formed by adding -ness to…','stubborn','stumble','strong','The suffix -ness makes an abstract noun from the adjective.','word-formation')]);
P('stud','Stud comes from Old English studu, “supporting post”; modern senses include a small fastener or knob, a breeding male animal, and covering a surface with many objects.',C('stud.s1','物件','She fastened the leather strap to the bag with a brass stud.','她用一枚黄铜铆钉把皮带固定在包上。','a collar/earring stud; brass studs','名词，指圆头小钉、扣件或耳钉；也可指种畜或动词“布满”。','a small metal fastener joins the strap.','物件'),M('The strap was held by a brass stud, a long loose cord that was not attached to the bag.','The strap was held by a brass stud fixed into the bag.','stud此处是固定带子的金属扣件，不是松散的绳子。','meaning'),[Q(1,'A brass stud on a bag is…','a small metal fastener','a long string of wins','a type of relaxed walk','Sense 1 is the fastening component.','meaning'),Q(1,'What did the stud do?','It fixed the strap to the bag','It removed the leather coating','It carried an injured person','The context states its fastening function.','context'),Q(1,'Which phrase is natural?','a pearl stud earring','a pearl studly earring','a stud of pearl earring','Stud commonly modifies a small earring style.','grammar'),Q(1,'Stud is historically related to Old English studu, “…”','supporting post','narrow band of color','medical attack','The old word referred to an upright support.','word-formation')]);
P('student','Student comes from Latin studentem, “one who is eager,” from studere, “be eager or study”; it names someone enrolled in education or seriously studying a subject.',[C('student.s1','教育','Each student must submit a lab report before Friday’s seminar.','每名学生都必须在周五研讨课前提交实验报告。','a school/university student; student ID','名词，指在学校或大学学习的人。','the learner has a class deadline.','教育'),C('student.s2','研究','As a student of migration history, Ravi compares records from three countries.','作为移民史研究者，拉维比较三个国家的档案。','a student of history/language; student of human nature','名词，也可指认真研究某一学科或主题的人。','he studies a subject deeply.','研究')],M('Each student submitted the lab report, but the sentence calls them people who never study.','Each student submitted the lab report as part of their course.','student指学习者，不能同时说这些人从不学习。','meaning'),[Q(1,'A student at a university is…','a person enrolled there to study','a teacher employed to grade the course','a lock component','Sense 1 is the educational meaning.','meaning'),Q(2,'A student of migration history is someone who…','seriously studies that subject','is necessarily enrolled at a school','refuses to examine records','Sense 2 allows a dedicated researcher, not only an enrolled learner.','context'),Q(1,'Which phrase is natural?','a student of biology','a student biology ofly','a studying student ofly biology','Of introduces the subject studied.','collocation'),Q(1,'Latin studere meant…','be eager or study','build a fort','scatter seeds','Student comes from a Latin word for an eager learner.','word-formation')]);
P('studio','Studio came into English from Italian studio, “study,” from Latin studium; it can be an artist’s workspace, a recording/film facility, or a small one-room flat.',[C('studio.s1','艺术','The painter rented a bright studio with north-facing windows.','画家租了一间明亮的画室，窗户朝北。','artist/photography studio; work in a studio','名词，指艺术家或设计师工作的房间。','workspace is rented for painting.','艺术'),C('studio.s2','媒体','The interview was recorded in a radio studio after the evening broadcast.','晚间节目播出后，这次采访在电台录音室录制。','recording/film studio; studio audience','名词，也指制作影片或录音的场所；还可指一室公寓。','recording equipment and interview indicate media facility.','媒体')],M('The interview was recorded in a radio studio, but the building contained no recording equipment or production space.','The interview was recorded in a radio studio equipped for broadcasts.','media studio是制作或录音的场所，不能与录制功能完全不符。','meaning'),[Q(1,'A painter’s studio is…','a room where the artist works','a long narrow stripe','a period of labor conflict','Sense 1 is the workspace meaning.','meaning'),Q(2,'Why was the interview recorded in a radio studio?','It is a facility for making broadcasts','It is a student enrolled in a course','It is a type of crop remnant','Sense 2 is the production facility.','context'),Q(1,'Which phrase is natural?','record a program in the studio','record a program at studioly','studio the program recording','In the studio identifies the recording location.','collocation'),Q(1,'Studio came into English from Italian…','studio','studius','studiation','The Italian noun is the source of the English form.','word-formation')]);
P('studious','Studious comes from Latin studiosus, “zealous, diligent,” from studium; it describes devotion to study or deliberate careful attention.',C('studious.s1','学习','The studious apprentice reviewed the repair manual every evening and kept detailed notes.','这名勤奋的学徒每晚都复习维修手册，并做下详细笔记。','a studious reader; studious attention','形容词，指勤于学习、认真钻研；也可表示刻意细致。','regular study and notes show diligence.','学习'),M('The studious apprentice never opened the manual and avoided all learning.','The studious apprentice reviewed the manual carefully each evening.','studious描述勤奋学习，与刻意逃避学习相反。','meaning'),[Q(1,'A studious apprentice is…','diligent about learning','unwilling to read or practice','a room for recording radio','The adjective describes dedication to study.','meaning'),Q(1,'What showed the apprentice was studious?','Reviewing the manual and taking notes each evening','Throwing the manual away','Changing the subject whenever asked','The example gives concrete evidence of diligent study.','context'),Q(1,'Which phrase is natural?','a studious reader','a studiously reader','a studiousness reader','Studious is an adjective modifying reader.','grammar'),Q(1,'Studious comes from Latin studiosus, meaning…','zealous or diligent','narrow or striped','stunned by a blow','The Latin source described eagerness and diligence.','word-formation')]);
P('study','Study comes through Old French estudie from Latin studium, “zeal, application”; it can mean learn, examine carefully, a room for work, or a piece of research.',[C('study.s1','学习','Noah studies marine biology for an hour before breakfast.','诺亚每天早餐前学习一小时海洋生物学。','study a subject; study for an exam','动词，指花时间学习一门学科。','scheduled learning is described.','学习'),C('study.s2','研究','Scientists studied the samples under a microscope before publishing the results.','科学家发表结果前用显微镜仔细研究了样本。','study a problem/sample; study carefully','动词，也指仔细检查或研究某事物。','close examination precedes a report.','研究'),C('study.s3','研究','The study found a link between sleep and memory in teenagers.','这项研究发现青少年睡眠与记忆之间存在联系。','a study of/on something; a recent study','名词，指一项研究；也可指供阅读写作的房间。','findings are reported from research.','研究')],M('Scientists studied the samples by never looking at them and drawing conclusions without evidence.','Scientists studied the samples carefully under a microscope.','study表示仔细查看或研究，不是完全不观察。','meaning'),[Q(1,'Noah studies marine biology means he…','spends time learning that subject','has written a research report already','works in a studio','Sense 1 is learning.','meaning'),Q(2,'Scientists studied samples under a microscope means they…','examined them carefully','memorized a poem','put them in a strongbox','Sense 2 is close investigation.','context'),Q(3,'A study found a link means a study is…','a piece of research','a lesson in a school only','a narrow strip','Sense 3 uses study as a research noun.','meaning'),Q(1,'Which phrase is natural?','study for an exam','study an exam for','study at for an exam','For introduces the purpose of preparation.','collocation')]);
P('stuff','Stuff is recorded through Old French estoffe, “material”; its deeper origin is uncertain. It means unnamed things or substance, to pack tightly, or the essential material of something.',[C('stuff.s1','物品','Put the camping stuff by the door so we can load the car quickly.','把露营用品放在门边，这样我们能很快装车。','a lot of stuff; stuff like books/clothes','名词，不可数，口语中泛指未具体命名的物品或材料。','miscellaneous equipment is gathered for a trip.','物品'),C('stuff.s2','装填','She stuffed the backpack with dry clothes before the storm arrived.','暴风雨到来前，她把干衣服塞满背包。','stuff something with; stuff into a bag','动词，指把东西塞进空间里直到装满。','clothes are packed into the bag.','装填'),C('stuff.s3','本质','The stuff of good journalism is careful reporting, not dramatic rumors.','好新闻的本质是认真报道，而不是耸人听闻的传言。','the stuff of legend/dreams; have the right stuff','名词，指构成某事的材料或某人的内在素质。','the essential quality is identified.','本质')],M('She stuffed the backpack with dry clothes by leaving the bag empty.','She stuffed the backpack with dry clothes until it was full.','stuff something with表示塞入、装满，空包与之不符。','meaning'),[Q(1,'“Camping stuff” is an informal way to refer to…','camping items without naming each one','only one exact tool','a serious disagreement','Sense 1 is the general things/substance meaning.','meaning'),Q(2,'She stuffed the backpack with clothes means she…','pushed clothes inside until it was full','removed all clothes from it','studied it carefully','Sense 2 is the verb meaning pack tightly.','context'),Q(3,'“The stuff of good journalism” means…','the essential qualities of good journalism','a bag of camping objects','a room for a painter','Sense 3 refers to the material or qualities something is made of.','meaning'),Q(1,'Which phrase is natural?','stuff the box with paper','stuff paper at the box with','stuffing the box by paper','With introduces what fills the container.','collocation')]);
P('stuffing','Stuffing is formed from stuff + -ing; it means soft material used to fill a cushion or toy, or a seasoned food mixture placed inside a dish before cooking.',[C('stuffing.s1','填充物','The old armchair sagged because its stuffing had shifted to one side.','旧扶手椅瘪了下去，因为里面的填充物移到了一侧。','cushion/toy stuffing; polyester stuffing','名词，指垫子、玩具或家具里的柔软填充材料。','internal filling has moved.','填充物'),C('stuffing.s2','烹饪','The roast chicken was served with onion-and-herb stuffing.','烤鸡配洋葱香草馅料一起上桌。','bread/cornbread stuffing; stuff a bird with','名词，指烹饪时塞入禽肉或蔬菜中的调味混合物。','seasoned mixture accompanies the roast.','烹饪')],M('The chair’s stuffing had shifted, so its empty seat became soft and evenly padded.','The chair’s stuffing had shifted, leaving one side flat and uncomfortable.','填充物移位会造成不均匀支撑，不会让空处更软。','meaning'),[Q(1,'Chair stuffing is…','soft filling inside the chair','a list of camping items','the outside fabric only','Sense 1 names internal padding.','meaning'),Q(2,'What was served with the chicken?','A seasoned onion-and-herb mixture','A paint stripper','A student’s report','Sense 2 is the cooked food mixture.','context'),Q(1,'Which phrase is natural?','bread stuffing for the roast','stuffingly bread for roast','stuffed of bread roast','Bread modifies stuffing as an ingredient.','grammar'),Q(1,'Stuffing is formed from stuff plus…','-ing','-er','-al','The noun names material used to fill something.','word-formation')]);
P('stuffy','Stuffy is formed from stuff + -y; it describes air that feels hot and stale, or a person/style that is overly formal and dull.',[C('stuffy.s1','空气','The meeting room felt stuffy, so Ana opened a window during the break.','会议室空气闷热不流通，因此安娜在休息时打开了窗户。','a stuffy room/office; feel stuffy','形容词，指空气不新鲜、闷热不舒服。','the open window lets in fresh air.','空气'),C('stuffy.s2','风格','The museum replaced its stuffy dress code with practical clothes for visitors.','博物馆取消了古板的着装规定，改为允许访客穿实用服装。','a stuffy atmosphere/club; stuffy formality','形容词，也指过分正式、乏味或守旧。','rigid dress rule is relaxed.','风格')],M('The stuffy room had cool, fresh air moving freely through every open window.','The stuffy room felt hot and airless until a window was opened.','stuffy描述闷热不通风，与清凉空气流通相反。','meaning'),[Q(1,'A stuffy meeting room feels…','hot and lacking fresh air','cool with a strong breeze','full of padded furniture','Sense 1 concerns air.','meaning'),Q(2,'A stuffy dress code is…','overly formal and old-fashioned','comfortable and practical','a strict but useful safety check','Sense 2 describes rigid formality.','context'),Q(1,'Which phrase is natural?','a stuffy office','a stuffily office','a stuffiness office','Stuffy is an adjective modifying office.','grammar'),Q(1,'Stuffy is formed from stuff plus…','-y','-ment','-er','The suffix creates an adjective describing a characteristic condition.','word-formation')]);
P('stumble','Stumble has an uncertain deeper origin; it means trip or nearly fall, falter while speaking, or find something unexpectedly.',[C('stumble.s1','行走','He stumbled over a raised paving stone but caught the rail before falling.','他被凸起的铺路石绊了一下，但在摔倒前抓住了栏杆。','stumble over a rock; stumble and fall','动词，指脚碰到障碍而失去平衡。','a raised stone catches his foot.','行走'),C('stumble.s2','表达','The witness stumbled over the street name while reading her statement aloud.','目击者朗读陈述时，在街道名称上结结巴巴。','stumble over a word/name; stumble through a speech','动词，也指说话或朗读时出错、停顿。','pronunciation falters on a difficult name.','表达'),C('stumble.s3','偶然发现','We stumbled across a small archive while looking for the town library.','我们找镇图书馆时偶然发现了一间小档案馆。','stumble across/on something; stumble upon a clue','动词短语，指意外或偶然发现某事物。','the archive was found by chance.','发现')],M('He stumbled over the raised stone by walking across it smoothly without losing balance.','He stumbled over the raised stone and grabbed the rail.','stumble over表示被障碍绊到，与平稳通过相反。','meaning'),[Q(1,'He stumbled over a paving stone means he…','caught his foot and nearly lost balance','walked smoothly without noticing it','found an archive by chance','Sense 1 is a physical trip.','meaning'),Q(2,'The witness stumbled over a street name means she…','faltered while saying it','tripped on the road','found the town library','Sense 2 describes difficulty during speech.','context'),Q(3,'They stumbled across an archive means they…','found it unexpectedly','built it themselves','walked past it knowingly','Sense 3 is chance discovery.','meaning'),Q(1,'Which phrase is natural?','stumble across an old letter','stumble an old letter acrossly','stumble to across an old letter','Across forms the phrasal verb for accidental discovery.','collocation')]);
P('stump','Stump is recorded in English from Old English and related Germanic forms; it means a tree remnant, a short remaining piece, or something that defeats someone.',[C('stump.s1','树木','A broad tree stump marked the spot where the oak had stood.','一棵宽大的树桩标记着橡树曾经生长的位置。','tree stump; stump of a tooth/limb','名词，指树被砍后留在地里的部分，也指残留短段。','the remaining base marks a former tree.','树木'),C('stump.s2','难题','The final riddle stumped the whole class until a student noticed the hidden pattern.','最后一道谜题难住了全班，直到一名学生发现隐藏规律。','stump someone; be stumped by a question','动词，指使某人答不上来或无法解决。','the class cannot solve the riddle at first.','难题'),C('stump.s3','政治','The candidate stumped across the state to speak at small-town meetings.','候选人走遍全州，在小镇集会上演讲。','stump for a candidate; stump the state','动词，指四处发表政治演说或为候选人助选。','the candidate travels from town to town speaking.','政治')],M('The riddle stumped the class, and every student solved it immediately without effort.','The riddle stumped the class until one student found the pattern.','stump someone指使其难以回答，与立刻轻松解出相反。','meaning'),[Q(1,'A tree stump is…','the part left in the ground after a tree is cut','a long narrow band of color','a relaxed walk','Sense 1 is the tree remnant.','meaning'),Q(2,'The riddle stumped the class means it…','left the students unable to solve it at first','was solved instantly by everyone','made them go on strike','Sense 2 is the verb meaning puzzle or defeat.','context'),Q(3,'A candidate who stumped across a state…','traveled around giving political speeches','cut down every tree','worked as a striker','Sense 3 concerns campaigning on the stump.','meaning'),Q(1,'Which phrase is natural?','the question stumped me','the question stump me yesterday','the question stumped to me','Stump takes the puzzled person as its direct object.','grammar')]);
P('stun','Stun is recorded in Middle English; its deeper derivation is debated. It means make someone briefly unconscious or shock them so strongly they cannot react.',[C('stun.s1','身体','The electric pulse stunned the attacker long enough for the guard to call for help.','电击使袭击者短暂失去行动能力，足够警卫呼叫援助。','stun a person/animal; be stunned unconscious','动词，指使人或动物短时间失去知觉或行动能力。','the effect is brief and physical.','身体'),C('stun.s2','震惊','The sudden resignation stunned the staff, who had expected the director to stay.','主任突然辞职让员工震惊不已，他们原以为主任会留下。','stun someone with/by; be stunned by news','动词，也指让某人震惊到一时无法反应。','unexpected news leaves staff shocked.','震惊')],M('The sudden resignation stunned the staff, who had expected it and were not surprised at all.','The sudden resignation stunned the staff because no one expected it.','stun在此表示强烈震惊，完全预料到则不会震惊。','meaning'),[Q(1,'The electric pulse stunned the attacker means it…','briefly made him unable to act','helped him walk normally','made him feel a relaxed stroll','Sense 1 is the physical incapacitation sense.','meaning'),Q(2,'The resignation stunned the staff because it…','shocked them unexpectedly','was announced long after everyone knew','made the office stuffy','Sense 2 is emotional shock.','context'),Q(1,'Which sentence is grammatical?','The news stunned the audience.','The news stunnedly the audience.','The news was stun the audience.','Stun is a transitive verb taking the affected person as object.','grammar'),Q(1,'The deeper derivation of stun is…','debated','certainly from Latin for a narrow stripe','certainly the suffix -ness','The word is recorded in Middle English, while earlier derivation is disputed.','word-formation')]);
P('stunned','Stunned is the past participle of stun; as an adjective it describes being too shocked to think or react, or briefly unconscious after a blow.',[C('stunned.s1','震惊','The stunned audience sat silently after the unexpected announcement.','出乎意料的公告之后，震惊的观众静静坐着。','look/feel stunned; be stunned by news','形容词，指震惊到无法清晰思考或立即反应。','the crowd is silent after surprising news.','震惊'),C('stunned.s2','受伤','The player lay stunned on the grass after a collision but soon sat up.','碰撞后，球员一度被撞得昏沉地躺在草地上，但很快坐了起来。','be stunned by a blow; lie stunned','形容词，指头部受击后短暂失去知觉或意识不清。','the blow causes temporary physical daze.','受伤')],M('The stunned audience reacted immediately with a planned speech before hearing the announcement.','The stunned audience sat in silence for a moment after the announcement.','stunned表示震惊到难以立即反应，与预先准备并立即发言相反。','meaning'),[Q(1,'A stunned audience is…','so shocked it cannot react at once','fully prepared for the announcement','a group of strikers','Sense 1 concerns emotional shock.','meaning'),Q(2,'Why did the player lie stunned?','A collision briefly dazed him','He took a relaxed walk','He was studying the match report','Sense 2 is the physical after-effect of a blow.','context'),Q(1,'Which phrase is natural?','stunned by the announcement','stunned of the announcement','stunningly by announcement','By introduces the cause of the shock.','collocation'),Q(1,'Stunned is the past participle of…','stun','stroll','strew','The adjective is built from the verb stun.','verb-form')]);
P('stunner','Stunner is formed from stun + -er; it can be an exceptionally attractive person or an event or object that is very impressive or surprising.',[C('stunner.s1','外貌','The model was a stunner in the emerald-green gown.','那位模特穿着祖母绿色礼服，美得令人惊艳。','a real stunner; look like a stunner','名词，非正式用法，指极其美丽动人的人。','appearance attracts admiration.','外貌'),C('stunner.s2','事物','The team’s late winning goal was a stunner that silenced the rival fans.','球队最后时刻的制胜进球令人震惊，对方球迷顿时安静下来。','a real stunner; a stunner of a result','名词，指令人赞叹或非常意外的事物。','unexpected goal impresses the crowd.','事物')],M('The final result was a stunner, a routine score that surprised and impressed absolutely no one.','The final result was a stunner that surprised the entire crowd.','stunner表示极令人惊讶或赞叹，不是毫无特别之处的常规结果。','meaning'),[Q(1,'Calling the model a stunner means she is…','extremely attractive','a worker taking part in a strike','a difficult question','Sense 1 is the informal person sense.','meaning'),Q(2,'Why was the late goal a stunner?','It was unexpected and silenced rival fans','It was an ordinary pass','It repaired a strongbox','Sense 2 names something impressive or surprising.','context'),Q(1,'Which phrase is natural?','a stunner of a goal','a stunnerly goal of','stunner to a goal','Of a goal is a common emphatic construction.','grammar'),Q(1,'Stunner is formed from stun plus…','-er','-ful','-ous','The suffix -er forms a noun for a person or thing producing an effect.','word-formation')]);
P('stunning','Stunning is formed from stun + -ing; it describes extreme beauty or an event so surprising that it leaves people amazed.',[C('stunning.s1','外貌','The restored theater looks stunning beneath its newly lit glass roof.','修复后的剧院在新装的玻璃屋顶灯光下美得惊人。','a stunning view/design; look stunning','形容词，指美得格外醒目、令人赞叹。','the appearance prompts admiration.','外貌'),C('stunning.s2','意外','The court issued a stunning decision that overturned the long-standing ruling.','法院作出一项令人震惊的决定，推翻了长期有效的裁决。','a stunning victory/blow/reversal; stunning news','形容词，也指非常意外、令人难以置信。','unexpected ruling reverses settled expectations.','意外')],M('The stunning view was dull and ordinary, and no one noticed it.','The stunning view was so beautiful that visitors stopped to admire it.','stunning强调格外美丽醒目，普通且无人注意与之不符。','meaning'),[Q(1,'A stunning theater looks…','extremely beautiful and impressive','plain and unnoticed','structurally unsafe by definition','Sense 1 is visual admiration.','meaning'),Q(2,'A stunning court decision is…','very surprising and unexpected','a routine decision everyone predicted','a small piece of tape','Sense 2 emphasizes surprise.','context'),Q(1,'Which sentence is natural?','She looked stunning in the blue dress.','She stunningly dress looked blue.','She was stunningly a dress.','Stunning is an adjective after looked.','grammar'),Q(1,'Stunning is based on the verb…','stun','stumble','stride','The -ing form describes a person or thing that causes amazement.','word-formation')]);
P('stunt','Stunt is recorded in English from the 19th century; its deeper origin is uncertain. It means a dangerous or impressive performance, or to hinder normal growth.',[C('stunt.s1','表演','The pilot performed a stunt over the airfield with permission from safety officials.','飞行员在安全官员许可下于机场上空完成了一次特技动作。','perform/do a stunt; a publicity stunt','名词，指为吸引注意而做的惊险或高难度动作。','an aerial maneuver is planned and impressive.','表演'),C('stunt.s2','生长','Severe lack of sunlight can stunt a young tree’s growth.','严重缺少阳光会阻碍幼树生长。','stunt growth/development; be stunted','动词，指阻碍正常生长或发展。','the tree fails to develop normally.','生长')],M('Lack of sunlight stunted the tree by helping it grow taller and faster than usual.','Lack of sunlight stunted the tree by limiting its normal growth.','stunt growth表示阻碍生长，促进快速长高与之相反。','meaning'),[Q(1,'A pilot’s stunt is…','a difficult or risky action performed for effect','a routine ticket stub','a series of students','Sense 1 is the performance meaning.','meaning'),Q(2,'Lack of sunlight can stunt a tree means it can…','hinder the tree’s growth','make it grow normally faster','make it stroll across a field','Sense 2 is the verb meaning inhibit development.','context'),Q(1,'Which phrase is natural?','a publicity stunt','a publicity stunted','a stunt of publicize','Stunt is a count noun modified by publicity.','collocation'),Q(1,'The deeper origin of stunt is…','uncertain','certainly from Latin for “build”','certainly a plural of student','Its modern senses are known, but the etymology is unsettled.','word-formation')]);
P('stuntman','Stuntman combines stunt + man; it names a male performer hired to carry out dangerous physical scenes in place of an actor.',C('stuntman.s1','影视','The stuntman rehearsed the fall onto padded boxes before the camera crew arrived.','摄制组到达前，特技演员先排练了摔到软垫箱上的动作。','film/stuntman; work as a stuntman','名词，指代替演员完成危险或高难度动作场面的男性表演者。','he practices a risky scene for a film.','影视'),M('The stuntman avoided all action scenes and was hired only to read the movie credits aloud.','The stuntman rehearsed and performed the dangerous fall for the actor.','stuntman的工作是代演危险动作，不是只朗读字幕。','meaning'),[Q(1,'A stuntman is hired to…','perform dangerous scenes in place of an actor','write all the dialogue','repair structural damage','That is the film-industry role.','meaning'),Q(1,'What did the stuntman rehearse?','A fall onto padded boxes','A radio interview','A long stroll by the canal','The context describes a planned physical action.','context'),Q(1,'Which phrase is natural?','the stuntman performed the jump','the stuntman performedly the jump','the stuntman stunted the jump','Stuntman is the subject who performs the stunt.','grammar'),Q(1,'Stuntman combines stunt with…','man','-ness','string','The compound names a male stunt performer.','word-formation')]);
P('stupid','Stupid comes from Latin stupidus, “amazed, dull,” from stupere, “be stunned”; it describes poor judgment or slow understanding, and can express annoyance.',[C('stupid.s1','判断','It was stupid to leave the laboratory door unlocked overnight.','实验室的门整夜没锁，这种做法很不明智。','a stupid mistake/idea; feel stupid','形容词，指不明智或理解力迟缓。','the careless choice creates a safety risk.','判断'),C('stupid.s2','恼火','This stupid printer has jammed again just before the deadline.','这台烦人的打印机又在截止时间前卡纸了。','this stupid machine; a stupid problem','非正式形容词，表示某物毫无道理地令人恼火。','recurring jam frustrates the speaker.','恼火')],M('Leaving the laboratory unlocked was a stupid decision that protected every chemical from theft.','Leaving the laboratory unlocked was a stupid decision that exposed chemicals to theft.','stupid此处表示不明智，错误做法不可能因此保护实验材料。','meaning'),[Q(1,'It was stupid to leave the lab unlocked means the choice was…','not sensible','carefully planned and safe','extremely beautiful','Sense 1 is poor judgment.','meaning'),Q(2,'“This stupid printer has jammed again” expresses…','annoyance at the machine','admiration for its design','a description of slow walking','Sense 2 is an informal expression of frustration.','context'),Q(1,'Which phrase is natural?','a stupid mistake','a stupidly mistake','a stupidity mistake','Stupid is the adjective modifying mistake.','grammar'),Q(1,'Latin stupidus was related to stupere, “…”','be stunned','bind tightly','scatter over a field','The Latin source referred to being dazed or amazed.','word-formation')]);
P('sturdiness','Sturdiness is formed from sturdy + -ness; it names strength of body or construction that resists damage or fatigue.',C('sturdiness.s1','质量','The sturdiness of the oak chair impressed the inspector, who tested each joint.','橡木椅的结实程度令检查员印象深刻，他逐一测试了每个接合处。','test/check sturdiness; sturdiness of a frame','名词，指身体或构造的结实、耐用程度。','the joints withstand deliberate pressure.','质量'),M('The chair’s sturdiness was clear because its joints broke under the lightest touch.','The chair’s sturdiness was clear because its joints held under pressure.','sturdiness表示牢固耐用，与轻碰即坏相反。','meaning'),[Q(1,'Sturdiness is…','strength that resists breaking or fatigue','a refusal to change an opinion','a medical emergency','That is the noun’s sense.','meaning'),Q(1,'How did the inspector assess the chair?','By testing each joint','By checking its color stripes','By measuring a swimmer’s stroke','The context connects sturdiness to structural testing.','context'),Q(1,'Which phrase is natural?','the sturdiness of the frame','the sturdy of the frame','the sturdiness frame ofly','Of introduces what has the quality.','grammar'),Q(1,'Sturdiness is formed from sturdy plus…','-ness','-ly','-er','The suffix -ness turns the adjective into an abstract noun.','word-formation')]);
P('sturdy','Sturdy is recorded in Middle English meaning strong or robust; its earlier derivation is uncertain. It describes a durable object, a healthy body, or a firm attitude.',[C('sturdy.s1','质量','The sturdy shelf held a row of heavy reference books without bending.','这块结实的搁板承住了一排厚重的参考书，没有弯曲。','a sturdy frame/shelf; sturdy shoes','形容词，指结构牢固、不易损坏。','the shelf supports a load without bending.','质量'),C('sturdy.s2','体格','Despite her small size, the sturdy child climbed the hill without tiring.','尽管身材小，这个健壮的孩子爬山时并不疲倦。','a sturdy child/build; sturdy health','形容词，也指身体健壮或态度坚定。','the child shows physical strength.','体格')],M('The sturdy shelf collapsed under one light book and could not support its own weight.','The sturdy shelf held several heavy books without bending.','sturdy表示牢固耐用，轻微负载就塌陷与之不符。','meaning'),[Q(1,'A sturdy shelf is…','strongly built and not easily damaged','made from loose string','very formal and dull','Sense 1 is construction strength.','meaning'),Q(2,'A sturdy child is…','healthy and physically strong','a child who refuses every idea','a child who has a stroke','Sense 2 applies sturdy to a person’s body.','context'),Q(1,'Which phrase is natural?','sturdy hiking boots','sturdily hiking boots','a sturdiness hiking boots','Sturdy is an adjective modifying boots.','grammar'),Q(1,'The earlier derivation of sturdy is…','uncertain','certainly from Latin for “study”','certainly a compound of strong and box','Middle English use is recorded, while its deeper source is not secure.','word-formation')]);
P('stutter','Stutter is recorded in English from the 17th century; its sound-imitative deeper origin is uncertain. It means speak with involuntary pauses/repetitions, or the speech condition itself.',[C('stutter.s1','表达','When nervous, Eli stuttered over the first sentence but continued with his presentation.','紧张时，伊莱在第一句话上结巴了一下，但仍继续作报告。','stutter over a word; stutter through a sentence','动词，指说话时突然停顿或不由自主地重复音节。','speech pauses and repeats under pressure.','表达'),C('stutter.s2','表达','The child’s stutter became less noticeable after speech therapy.','接受言语治疗后，这个孩子的口吃症状不再那么明显。','have/develop a stutter; speech stutter','名词，指说话时无法控制地重复声音或音节的习惯。','the noun names a speech condition.','表达')],M('Eli stuttered through the sentence with perfectly smooth speech and no pauses or repeated sounds.','Eli stuttered through the sentence, repeating its opening sound before continuing.','stutter表示说话停顿或重复音节，与流畅无停顿相反。','meaning'),[Q(1,'Eli stuttered over the first sentence means he…','paused or repeated sounds while speaking','walked proudly into the room','read it smoothly without hesitation','Sense 1 is the verb describing disrupted speech.','meaning'),Q(2,'A child’s stutter is…','a speech habit involving uncontrolled repetitions or pauses','a narrow stripe on clothing','a strong opinion','Sense 2 is the noun for the speech condition.','context'),Q(1,'Which phrase is natural?','stutter over a difficult name','stutter a difficult name overly','stutterly over on a name','Over marks the word that causes difficulty.','collocation'),Q(1,'The deeper origin of stutter is…','uncertain and possibly sound-imitative','certainly Latin for “build”','a compound of study and student','The word’s history is not securely traced beyond its English record.','word-formation')]);
P('sty','Sty is recorded in Old English as stig, an enclosure or hall; the modern noun means a pig enclosure and figuratively a filthy place.',C('sty.s1','环境','After the harvest festival, the neglected yard looked like a sty.','丰收节后，没人打理的院子看起来像个猪圈。','a pigsty; a sty of a room','名词，指猪圈；也可比喻肮脏杂乱的地方。','the yard is filthy and untidy.','环境'),M('The kitchen was a sty, with every surface spotless and all dishes put away.','The kitchen was a sty, with dirty dishes and waste scattered around.','比喻义sty指肮脏杂乱的地方，整洁无污与其相反。','meaning'),[Q(1,'A pig sty is…','an enclosure where pigs are kept','a music recording room','a report’s organization','Sense 1 is the literal animal enclosure.','meaning'),Q(1,'Why did the yard look like a sty?','It was neglected and messy','Every surface was clean','It was a stronghold','The example uses the figurative sense of a filthy place.','context'),Q(1,'Which phrase is natural?','clean out the pigsty','cleanly out the stying','sty of clean out','Pigsty is the compound for a pig enclosure.','grammar'),Q(1,'Sty was recorded in Old English as…','stig','studium','struere','The Old English form referred to an enclosure or hall.','word-formation')]);
P('style','Style comes from Latin stilus, a writing instrument; it later developed the senses manner, design, and arrange or shape something.',[C('style.s1','表达','The editor praised Jun’s clear writing style but asked for stronger evidence.','编辑称赞了小君清晰的写作风格，但要求补充更有力的证据。','writing/teaching style; in the style of','名词，指做事、写作或表达的特定方式。','the editor comments on manner of writing.','表达'),C('style.s2','设计','That coat is back in style this winter after being absent for years.','那件大衣多年不流行之后，今年冬天又重新时兴起来。','in/out of style; a style of clothing','名词，也指某时期流行的服装、发型或设计样式。','fashion trend returns.','设计'),C('style.s3','造型','The designer styled the room in pale green and natural wood.','设计师把房间布置成浅绿色搭配天然木材的风格。','style something in/after; be styled as','动词，指按特定方式设计或造型。','the room is given a chosen look.','造型')],M('The editor praised Jun’s writing style, although the sentence says he had no consistent way of writing.','The editor praised Jun’s clear and consistent writing style.','style作名词指写作方式，完全没有一致方式与赞扬的具体对象不符。','meaning'),[Q(1,'Jun’s writing style is…','his particular way of writing','a room where recordings are made','a speech interruption','Sense 1 concerns manner.','meaning'),Q(2,'A coat back in style is…','fashionable again','a research study','a pig enclosure','Sense 2 concerns fashion.','context'),Q(3,'The designer styled the room means the designer…','arranged its appearance in a chosen way','studied the room silently','made it structurally unsafe','Sense 3 is the verb meaning design or shape.','meaning'),Q(1,'Style comes from Latin stilus, a…','writing instrument','type of pig enclosure','word for strict rules','The historical Latin word referred to a tool for writing.','word-formation')]);
P('stylish','Stylish is formed from style + -ish; it describes something fashionable or graceful and well designed.',[C('stylish.s1','时尚','She found a stylish winter coat that fit her budget and kept her warm.','她找到一件时髦又符合预算的冬季大衣，穿着也很暖和。','stylish clothes/design; look stylish','形容词，指符合潮流、外观时尚。','the coat is fashionable as well as practical.','时尚'),C('stylish.s2','品味','The small hotel combines stylish rooms with practical storage for guests.','这家小酒店把设计优雅的客房与实用的储物空间结合起来。','stylish surroundings/furniture; a stylish design','形容词，也指优雅且设计得体、体现好品味。','the design is graceful and useful.','品味')],M('She wore a stylish coat that looked clumsy, poorly designed, and out of fashion.','She wore a stylish coat with a graceful, current design.','stylish表示时尚或设计优雅，与笨拙过时的外观相反。','meaning'),[Q(1,'A stylish winter coat is…','fashionable in appearance','an enclosed pen for pigs','a thick book report','Sense 1 is current fashion.','meaning'),Q(2,'Stylish hotel rooms have…','graceful, well-designed surroundings','no design or taste','a heavy lock on every door','Sense 2 emphasizes good design.','context'),Q(1,'Which phrase is natural?','a stylish jacket','a stylishly jacket','a styleish jacketly','Stylish is the adjective modifying jacket.','grammar'),Q(1,'Stylish is formed from style plus…','-ish','-ment','-er','The suffix -ish forms an adjective related to or having the quality of style.','word-formation')]);
P('stylist','Stylist is formed from style + -ist; it names a person who creates a look for clothes, hair, or production, or a writer known for literary style.',[C('stylist.s1','造型','The stylist chose simple stage clothes that matched the singer’s movement.','造型师挑选了与歌手动作相衬的简洁舞台服装。','fashion/hair stylist; work as a stylist','名词，指负责服装、发型或演出视觉效果的人。','the professional selects costumes for a performer.','造型'),C('stylist.s2','文体','The reviewer called her a precise stylist whose sentences were short and vivid.','评论家称她是文风精练的作家，句子简短而生动。','a prose stylist; a stylist of great skill','名词，也指以讲究文笔著称的作家或评论者。','careful sentence style is the focus.','文体')],M('The fashion stylist selected the singer’s clothes, but the sentence identifies the stylist as the person who wrote the review.','The fashion stylist selected clothes for the singer’s stage appearance.','服装造型师负责视觉造型，不是撰写评论的文体作家。','distinction'),[Q(1,'A fashion stylist is…','a person who creates a clothing look','a student of migration history','a worker on strike','Sense 1 is the appearance-related job.','meaning'),Q(2,'A prose stylist is known for…','careful and distinctive writing','designing a recording studio','building a tree stump','Sense 2 concerns literary style.','context'),Q(1,'Which phrase is natural?','a hair stylist','a hair styleist person','a stylist of hairing','Hair identifies the stylist’s area of work.','grammar'),Q(1,'Stylist is formed from style plus…','-ist','-less','-ful','The suffix -ist names a person associated with an activity or field.','word-formation')]);
P('stylistic','Stylistic is formed from style + -istic; it means relating to manner of expression or design rather than to factual content.',C('stylistic.s1','写作','The two essays make the same argument but differ in stylistic choices and tone.','两篇文章提出相同论点，但在文体选择和语气上有所不同。','stylistic choice/feature; stylistic analysis','形容词，指涉及表达方式、写作风格或设计风格。','content matches while manner differs.','写作'),M('The essays have different stylistic choices because one argues for a different factual conclusion, though their tone and wording are identical.','The essays have different stylistic choices in tone and wording despite sharing the same conclusion.','stylistic指表达方式差异；仅论点不同且语气措辞相同并不构成文体差异。','distinction'),[Q(1,'Stylistic choices concern…','the manner of expression','whether facts are true only','the length of a stride','The adjective relates to style, not factual content itself.','meaning'),Q(1,'How do the two essays differ?','In tone and stylistic choices','In their conclusion only','In the number of students','The example says the argument is the same but the manner differs.','context'),Q(1,'Which phrase is natural?','a stylistic feature of the poem','a stylisticly feature of the poem','a style featurely poem','Stylistic is an adjective modifying feature.','grammar'),Q(1,'Stylistic is based on the noun…','style','stutter','stun','The word is built from style with an adjectival suffix.','word-formation')]);
P('stylize','Stylize is formed from style + -ize; it means represent something using a conventional or simplified artistic manner rather than lifelike detail.',C('stylize.s1','艺术','The illustrator stylized the birds as simple geometric shapes for the children’s map.','插画师把鸟画成简单的几何形状，用在儿童地图上。','stylize a figure/scene; stylize something as','动词，指按程式化、简化或装饰性的方式表现事物。','natural forms are deliberately simplified.','艺术'),M('The illustrator stylized the birds by copying every feather and shadow with photographic realism.','The illustrator stylized the birds as simple geometric shapes.','stylize强调程式化或简化表现，不是逐细节写实复制。','meaning'),[Q(1,'The illustrator stylized the birds means she…','represented them in a simplified artistic manner','copied every detail photorealistically','made them fly out of the map','That is the verb’s artistic sense.','meaning'),Q(1,'Why were the birds drawn as geometric shapes?','To create a simple visual style for children','To record their exact anatomy','To illustrate a medical stroke','The context says the design was deliberately simplified.','context'),Q(1,'Which construction is natural?','stylize a scene as a pattern','stylize a scene to patterningly','stylization a scene as pattern','Stylize can take an object plus as and the chosen form.','grammar'),Q(1,'Stylize is formed from style plus…','-ize','-ness','-ist','The suffix -ize forms a verb meaning give or represent in a certain style.','word-formation')]);
P('stylized','Stylized is the past participle of stylize; it describes representation according to an artistic convention rather than realistic detail.',C('stylized.s1','艺术','The dance used stylized gestures instead of trying to copy ordinary movements exactly.','这段舞蹈使用了程式化手势，而不是试图精确模仿日常动作。','stylized image/gesture; a highly stylized form','形容词，指按固定艺术程式表现、非写实的。','conventional gestures replace realistic imitation.','艺术'),M('The stylized portrait reproduced every pore and shadow with exact photographic realism.','The stylized portrait reduced the face to a few conventional lines.','stylized表示程式化处理，与逐细节照片般写实相反。','meaning'),[Q(1,'Stylized gestures are…','represented according to an artistic convention','exact copies of ordinary movements','a type of labor protest','The adjective describes conventionalized rather than literal movement.','meaning'),Q(1,'What did the dance avoid?','Copying ordinary movement exactly','Using any gesture','Following a style','The context contrasts stylization with exact imitation.','context'),Q(1,'Which phrase is natural?','a stylized portrait','a stylizedly portrait','a style-ized portraiting','Stylized is the adjective modifying portrait.','grammar'),Q(1,'Stylized is the past participle of…','stylize','stun','strew','The adjective comes from the verb stylize.','verb-form')]);
P('sub','As a standalone English noun, sub is a clipping used for submarine, substitute player, or submarine sandwich; its exact expansion depends on context.',[C('sub.s1','海军','The sub surfaced near the harbor after spending two days underwater.','潜艇在水下航行两天后于港口附近浮出水面。','a nuclear/attack sub; serve on a sub','名词，submarine的非正式简称，指潜艇。','the vessel travels below the sea.','海军'),C('sub.s2','体育','The coach brought on a sub when the midfielder injured his ankle.','中场球员脚踝受伤后，教练换上了一名替补。','bring on/send in a sub; substitute player','名词，指比赛中替换另一名球员的替补。','one player replaces an injured teammate.','体育'),C('sub.s3','饮食','We ordered a turkey sub from the sandwich shop near the station.','我们在车站附近的三明治店点了一份火鸡潜艇堡。','a meat/cheese sub; order a sub','名词，非正式指切开后夹肉、奶酪或蔬菜的长面包。','filled long roll is ordered for lunch.','饮食')],M('The coach brought on a sub to replace the injured midfielder, then left the substitute player on the bench.','The coach brought on a sub, sending the replacement player onto the field.','体育义sub就是替补球员，不会仍留在场边而未上场。','meaning'),[Q(1,'A sub that surfaced near a harbor is…','a submarine','a substitute player','a long filled sandwich','Sense 1 is the clipped naval noun.','meaning'),Q(2,'The coach brought on a sub means the coach…','put a replacement player into the match','ordered lunch for the team','sent a submarine underwater','Sense 2 is the sports meaning.','context'),Q(3,'A turkey sub from a sandwich shop is…','a filled long bread roll','a player replacement','a small research room','Sense 3 is the food meaning.','meaning'),Q(1,'The exact expansion of sub depends on…','the context','whether it is capitalized only','its plural ending','Sub is a clipping with several unrelated full forms.','word-formation')]);
P('subclass','Subclass combines sub- “under, secondary” with class; it is a division within a larger class, especially in classification.',C('subclass.s1','分类','In this system, each subclass groups species that share a more specific trait.','在这个分类系统中，每个亚类都归纳具有更具体共同特征的物种。','a subclass of; divide into subclasses','名词，指较大类别之下的次级类别。','a nested taxonomic group is described.','分类'),M('The chart labels mammals a subclass of reptiles, although mammals are not classified within reptiles.','The chart divides the larger group into accurate subclasses.','分类关系必须真实；把哺乳动物列为爬行动物的亚类是错误的。','meaning'),[Q(1,'A subclass is…','a division inside a larger class','a class with no members','a type of submarine','The prefix signals a lower-level category.','meaning'),Q(1,'What does each subclass group?','Species sharing a more specific trait','All animals without any shared feature','People who walk slowly','The context describes nested biological classification.','context'),Q(1,'Which phrase is natural?','a subclass of insects','a subclass insects ofly','a sub of class insects','Of introduces the larger class.','grammar'),Q(1,'In subclass, the prefix sub- means…','under or at a lower level','across a surface','very strict','The prefix marks a category subordinate to a larger one.','word-formation')]);
P('subcommittee','Subcommittee combines sub- “under, smaller” with committee; it is a smaller group selected from a committee to examine a specific matter.',C('subcommittee.s1','组织','The housing subcommittee will report its recommendations to the full council next month.','住房小组委员会将在下个月向全体委员会提交建议。','appoint/form a subcommittee; subcommittee report','名词，指从较大委员会中选出的、负责专项事务的小组。','a smaller group reviews one topic and reports back.','组织'),M('The housing subcommittee replaced the full council and did not report its work to anyone.','The housing subcommittee investigated housing and reported to the full council.','subcommittee是较大委员会下属的小组，通常负责专项调查并回报。','meaning'),[Q(1,'A subcommittee is…','a smaller group chosen from a committee','the entire city council','a group of students in a class','The prefix and definition indicate a subordinate group.','meaning'),Q(1,'What will the housing subcommittee do?','Report recommendations to the full council','Replace every council member','Build a stronghold','The context describes its review and report.','context'),Q(1,'Which phrase is natural?','appoint a subcommittee to review housing','appoint housing subcommittee to reviewly','a subcommittee appoint of housing','Appoint a group to review a subject is natural.','grammar'),Q(1,'Subcommittee is formed from sub- plus…','committee','sturdy','study','The compound names a smaller committee within a larger one.','word-formation')]);
P('subconscious','Subconscious combines sub- “below” with conscious; it describes thoughts, feelings, or processes operating beneath conscious awareness.',C('subconscious.s1','心理','A subconscious bias can affect hiring decisions even when interviewers believe they are being fair.','即使面试官认为自己公平，潜意识偏见仍可能影响招聘决定。','subconscious thought/bias; the subconscious mind','形容词，指在清醒意识之下存在或起作用的。','the influence operates without deliberate awareness.','心理'),M('A subconscious bias affected the interviewers only after they became fully aware of it and chose to apply it.','A subconscious bias influenced the interviewers without their deliberate awareness.','subconscious作用于意识之下，不是有意识地选择使用偏见。','meaning'),[Q(1,'A subconscious bias operates…','below deliberate awareness','only after a person consciously chooses it','as a physical stripe','That is the meaning of subconscious.','meaning'),Q(1,'How could it affect hiring?','It can influence decisions without interviewers noticing','It forces every interviewer to announce a bias','It changes the building’s structure','The context highlights an unrecognized influence.','context'),Q(1,'Which phrase is natural?','a subconscious reaction','a subconsciousness react','a subconscious of reaction','Subconscious is an adjective modifying reaction.','grammar'),Q(1,'In subconscious, sub- means…','below','across','very','The prefix signals activity below the level of awareness.','word-formation')]);
P('subcontract','Subcontract combines sub- with contract; it names an arrangement where a main contractor gives part of a job to another firm, or the act of doing so.',C('subcontract.s1','工程','The builder subcontracted the electrical work to a licensed local company.','建筑商把电气工程分包给一家持证的本地公司。','subcontract work to a firm; a subcontract agreement','动词，指主承包方把部分工作交由另一家公司完成；也可作名词。','a specialist firm receives part of the project.','工程'),M('The builder subcontracted the electrical work by refusing to let any outside company perform it.','The builder subcontracted the electrical work to a licensed specialist.','subcontract指把部分工作交给外部承包方，不是拒绝分包。','meaning'),[Q(1,'The builder subcontracted electrical work means the builder…','hired another firm to do part of the project','performed every task alone','cancelled the whole project','That is the verb meaning of subcontract.','meaning'),Q(1,'Who received the electrical work?','A licensed local company','The housing subcommittee','A student of engineering','The context identifies the specialist contractor.','context'),Q(1,'Which construction is natural?','subcontract the work to a firm','subcontract a firm the work at','subcontracting to the work a firm','To introduces the firm receiving the task.','grammar'),Q(1,'The prefix sub- in subcontract suggests…','a secondary or lower-level contract','a conscious decision','a narrow strip','The main contractor passes part of the contract down to another firm.','word-formation')]);
P('subculture','Subculture combines sub- “within/below” with culture; it names a cultural group inside a larger society with its own norms or tastes.',C('subculture.s1','社会','The documentary follows a skating subculture that developed around the city’s old warehouses.','这部纪录片追踪了在城市旧仓库周边发展起来的滑板亚文化。','youth/urban subculture; part of a subculture','名词，指较大社会内部有自身规范与兴趣的小群体文化。','shared skating practices distinguish a group within the city.','社会'),M('The skating subculture had no shared interests or customs and included every resident in the country.','The skating subculture shared interests and customs within the wider city.','subculture指较大社会中的特定文化群体，不是全社会且毫无共同点。','meaning'),[Q(1,'A subculture is…','a cultural group within a larger society','the whole society with no smaller groups','a subcommittee in government','The prefix marks an internal subgroup.','meaning'),Q(1,'What links the skating subculture in the documentary?','Shared skating interests and practices','A common job at the warehouse','A rule that everyone must join','The context identifies a community within the city.','context'),Q(1,'Which phrase is natural?','a subculture within a larger society','a subculture underly largerly society','the society subculture all residents','Within describes its place inside a wider culture.','grammar'),Q(1,'Subculture combines sub- with…','culture','sturdy','strike','The compound means a smaller cultural group within a larger one.','word-formation')]);
P('subdiscipline','Subdiscipline combines sub- “smaller or subordinate” with discipline; it means a narrower field within a broader academic subject.',C('subdiscipline.s1','学术','Glaciology is a subdiscipline of earth science focused on ice and glaciers.','冰川学是地球科学的一个分支，专门研究冰与冰川。','a subdiscipline of biology/history; academic subdiscipline','名词，指某一学科内部更窄的研究领域。','a specialized field sits within a broader one.','学术'),M('Glaciology is a subdiscipline of earth science, but it covers every field of knowledge outside earth science.','Glaciology is a specialized subdiscipline within earth science.','subdiscipline是较大学科内的子领域，不是涵盖其外的全部知识。','meaning'),[Q(1,'A subdiscipline is…','a narrower field within a broader subject','a subject broader than every field','a group formed to review one issue','The prefix indicates a subordinate academic field.','meaning'),Q(1,'Glaciology focuses on…','ice and glaciers','the style of poems','labor contracts','The context specifies its specialized topic.','context'),Q(1,'Which phrase is natural?','a subdiscipline of earth science','a subdiscipline earth science forly','earth science of subdiscipline','Of introduces the broader discipline.','grammar'),Q(1,'Subdiscipline combines sub- with…','discipline','stun','stubble','The compound names a specialized subdivision of a field.','word-formation')]);
P('subdivide','Subdivide combines sub- “further” with divide; it means split a section or group into smaller parts again.',C('subdivide.s1','分类','The editor subdivided the chapter into three case studies with separate headings.','编辑把这一章再分成三个案例研究，并分别加上标题。','subdivide into sections/groups; further subdivide','动词，指把已分出的部分继续分成更小部分。','one chapter is split into smaller sections.','分类'),M('The editor subdivided the chapter by merging all three case studies into one undivided block.','The editor subdivided the chapter into three clearly marked case studies.','subdivide是继续拆分，而不是把各部分合并成一块。','meaning'),[Q(1,'The editor subdivided the chapter means the editor…','split it into smaller parts','combined all sections into one','removed the chapter from the book','The prefix suggests further division.','meaning'),Q(1,'How many case studies resulted?','Three','One hundred','None','The context gives the resulting number.','context'),Q(1,'Which phrase is natural?','subdivide the land into plots','subdivide the land at plots','subdivision the land into plot','Into introduces the smaller resulting parts.','collocation'),Q(1,'Subdivide is formed from sub- plus…','divide','style','stun','The prefix adds the idea of dividing further.','word-formation')]);
P('subdivision','Subdivision combines sub- with division; it names one smaller part of a larger whole, or a residential area divided into lots.',C('subdivision.s1','结构','Each subdivision of the report has a different reviewer and deadline.','报告的每个分部都有不同的审阅人和截止时间。','a subdivision of a chapter/field; divide into subdivisions','名词，指整体再分之后得到的较小部分。','the large report is divided into smaller sections.','结构'),M('Each subdivision of the report included the entire report unchanged and had no distinct part.','Each subdivision covered a separate section of the report.','subdivision指被划分出来的较小部分，不是未拆分的整体。','meaning'),[Q(1,'A subdivision of a report is…','one smaller part of the whole','the whole report repeated unchanged','a person who strikes for wages','Sense 1 is a smaller division.','meaning'),Q(1,'What was different for each subdivision?','Its reviewer and deadline','Its language and alphabet','Its paint color','The context shows distinct parts with separate assignments.','context'),Q(1,'Which phrase is natural?','a subdivision of the chapter','a subdivision the chapter ofly','a chapter subdivision into of','Of introduces the larger whole being divided.','grammar'),Q(1,'Subdivision is formed from sub- and…','division','sturdiness','stutter','The noun names a smaller resulting division.','word-formation')]);
P('subduct','Subduct comes from Latin subducere, “draw or lead under”; in geology it means move one lithospheric plate beneath another.',C('subduct.s1','地质','At the trench, dense oceanic crust subducts beneath the continental plate.','在海沟处，密度较大的洋壳俯冲到大陆板块之下。','a plate subducts beneath another; subduct under','动词，指使岩石圈板块向下插入相邻板块之下。','one plate descends beneath another at a trench.','地质'),M('At the trench, the oceanic plate subducted upward over the continental plate.','At the trench, the oceanic plate subducted beneath the continental plate.','subduct表示向下进入另一板块之下，不是向上覆盖。','meaning'),[Q(1,'Oceanic crust subducts means it…','moves downward beneath another plate','rises above every neighboring plate','forms a string of islands by walking','That is the geological verb.','meaning'),Q(1,'Where does the dense oceanic crust move?','Beneath the continental plate','Over the continental plate','Into the atmosphere','The context gives the direction and neighboring plate.','context'),Q(1,'Which phrase is natural?','the oceanic plate subducts beneath the continent','the oceanic plate subducts above the continent','the oceanic plate subductly the continent','Beneath marks the downward relation in this geological sense.','collocation'),Q(1,'Latin subducere meant…','draw or lead under','style in a conventional way','speak with pauses','The Latin source matches the downward movement in geology.','word-formation')]);
P('subduction','Subduction is formed from subduct + -ion; it names the geological descent of one lithospheric plate beneath another into the mantle.',C('subduction.s1','地质','The earthquake risk is high along the subduction zone where the oceanic plate sinks below the continent.','在洋壳沉入大陆之下的俯冲带附近，地震风险很高。','a subduction zone; subduction of one plate beneath another','名词，指一块板块俯冲到另一块板块下方并进入地幔的过程。','the plate descends below another at a zone.','地质'),M('The subduction zone marked a place where one plate rose above the other and never descended.','The subduction zone marked where one plate sank beneath another.','subduction是板块向下插入另一板块之下的过程。','meaning'),[Q(1,'Subduction is…','the descent of one tectonic plate beneath another','the rise of both plates into the sky','the division of a report','That is the geological process.','meaning'),Q(1,'Why is earthquake risk high there?','A plate sinks beneath another along the zone','The plates are completely motionless','A subcommittee is meeting','The context connects the boundary with plate movement.','context'),Q(1,'Which phrase is natural?','a subduction zone','a subductionly zone','a subduct of zone','Subduction is the noun naming the process and zone.','grammar'),Q(1,'Subduction is formed from subduct plus…','-ion','-ness','-ish','The suffix -ion forms a noun for the process.','word-formation')]);
P('subdue','Subdue came through Old French subduer from Latin subducere, “bring under”; it means force into control, quiet an animal, or lessen light, sound, or feeling.',[C('subdue.s1','控制','Police negotiated for hours before moving in to subdue the violent crowd.','警方经过数小时谈判后才介入制服暴力人群。','subdue a rebellion/crowd; subdue by force','动词，指用力量或权威使人群、对手服从或受控制。','the crowd is brought under control.','控制'),C('subdue.s2','动物','The trainer used calm, consistent handling to subdue the frightened horse.','驯马师用平静而持续的方式安抚受惊的马，使它安静下来。','subdue an animal; subdue someone’s fear','动词，也指使动物或人安静、易于控制。','calm handling settles the animal.','动物'),C('subdue.s3','减弱','She chose matte curtains to subdue the glare from the afternoon sun.','她选了哑光窗帘来减弱午后阳光的刺眼反光。','subdue light/sound/anger; subdue the colors','动词，还可指使光、声音或情绪不那么强烈。','curtains reduce the brightness.','减弱')],M('The curtains subdued the glare by reflecting more bright sunlight into the room.','The curtains subdued the glare by reducing the reflected sunlight.','subdue光线表示减弱刺眼程度，不是增加亮度。','meaning'),[Q(1,'Police moved to subdue the crowd means they tried to…','bring it under control','encourage it to grow','walk slowly among it','Sense 1 is control by force or authority.','meaning'),Q(2,'The trainer subdued the frightened horse by…','calming it so it became easier to control','making it more frightened and uncontrollable','letting it run away','Sense 2 concerns quieting an animal.','context'),Q(3,'Curtains that subdue glare…','make the light less intense','make the light brighter','make the room structurally weak','Sense 3 means lessen intensity.','meaning'),Q(1,'Subdue came through Old French from Latin meaning…','bring under','scatter widely','walk with long steps','The historical sense of bringing under control aligns with the modern verb.','word-formation')]);
})();
